local IntroRandom = Random.new()

local function IntroTween(obj, duration, props, style, direction)
    local tween = TweenService:Create(
        obj,
        TweenInfo.new(
            duration,
            style or Enum.EasingStyle.Quad,
            direction or Enum.EasingDirection.Out
        ),
        props
    )
    tween:Play()
    return tween
end

