local function ClampPosition(pos, size)
    local vp =
        GetViewport()

    local hx =
        size.X / 2

    local hy =
        size.Y / 2

    local keepX =
        math.min(
            96,
            size.X * 0.32
        )

    local keepY =
        math.min(
            76,
            size.Y * 0.32
        )

    return Vector2.new(
        math.clamp(
            pos.X,
            keepX - hx,
            vp.X - keepX + hx
        ),
        math.clamp(
            pos.Y,
            keepY - hy,
            vp.Y - keepY + hy
        )
    )
end

