local function AddCorner(obj, radius)
    local c = Instance.new("UICorner")
    c.CornerRadius = UDim.new(0, radius)
    c.Parent = obj
    return c
end

local function StartRainbowFlow(parent, duration, transparency)
    local grad = Instance.new("UIGradient")
    grad.Name = "RainbowFlow"
    grad.Color = RAINBOW_FLOW
    grad.Transparency = transparency or NumberSequence.new(0)
    grad.Rotation = -180
    grad.Parent = parent

    local tw = TweenService:Create(
        grad,
        TweenInfo.new(
            duration or 2.0,
            Enum.EasingStyle.Linear,
            Enum.EasingDirection.InOut,
            -1,
            false,
            0
        ),
        {Rotation = 180}
    )
    tw:Play()

    return grad, tw
end

local function AddRainbowBorder(
    obj,
    thickness,
    transparency,
    speed
)
    thickness = thickness or 0.9
    local flowSpeed = speed or 1.95

    -- V98：
    -- 放弃外层雾化泛光，只保留一条清晰的彩虹流动描边。
    local stroke =
        Instance.new(
            "UIStroke"
        )

    stroke.Name =
        "DB_RainbowMain"

    stroke.ApplyStrokeMode =
        Enum.ApplyStrokeMode.Border

    stroke.Thickness =
        thickness

    stroke.Color =
        Color3.new(
            1,
            1,
            1
        )

    stroke.Transparency =
        transparency
        or 0.01

    stroke.LineJoinMode =
        Enum.LineJoinMode.Round

    stroke.Parent =
        obj

    local grad =
        StartRainbowFlow(
            stroke,
            flowSpeed
        )

    return stroke,
        grad
end


