local DBVisualSettings

local function AddDBEnchantedBorder(
    obj,
    thickness,
    auraEnabled
)
    thickness = thickness or 0.9

    for _, child in ipairs(obj:GetChildren()) do
        if child.Name == "DB_EnchantMain"
        or child.Name == "DB_EnchantCrystal"
        or child.Name == "DB_InternalPlainStroke" then
            child:Destroy()
        end
    end

    local stroke = Instance.new("UIStroke")
    stroke.Name = "DB_InternalPlainStroke"
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Thickness = thickness
    stroke.Color = Color3.fromRGB(255, 255, 255)
    local baseTransparency = 0.50
    stroke:SetAttribute("DB_BaseTransparency", baseTransparency)

    local bordersEnabled = true
    if DBVisualSettings
    and DBVisualSettings.ButtonBordersEnabled ~= nil
    and obj:IsA("TextButton") then
        bordersEnabled = DBVisualSettings.ButtonBordersEnabled
    end

    stroke.Transparency = bordersEnabled and baseTransparency or 1
    stroke.LineJoinMode = Enum.LineJoinMode.Round
    stroke.Parent = obj
    return stroke, nil, nil
end

local function AddDBEnchantedText(
    label,
    stronger
)
    -- V91：
    -- 原来这里会加蓝/青/紫渐变和蓝色描边。
    -- 现在全部统一成普通、高亮、纯白文字。
    for _, child in ipairs(
        label:GetChildren()
    ) do
        if child:IsA("UIGradient") then
            child:Destroy()
        end
    end

    label.TextColor3 =
        Color3.fromRGB(
            255,
            255,
            255
        )

    label.TextStrokeTransparency = 1

    return nil
end


------------------------------------------------------------
-- 轻量化“附魔光点”特效
-- 参考：高级附魔/结界感的闪烁光点，不做重型粒子，
-- 用不均匀分布的小光点 + 晶体菱形点来模拟。
------------------------------------------------------------
local function AddDBEnchantedDust(
    parent,
    options
)
    options =
        options
        or {}

    local count =
        options.Count
        or 14

    local minSize =
        options.MinSize
        or 1

    local maxSize =
        options.MaxSize
        or 3

    local zIndex =
        options.ZIndex
        or (
            (parent.ZIndex or 1)
            + 1
        )

    local minTransparency =
        options.MinTransparency
        or 0.46

    local maxTransparency =
        options.MaxTransparency
        or 0.82

    local drift =
        options.Drift
        or 0.020

    local clusterCount =
        math.max(
            1,
            options.ClusterCount
            or 3
        )

    local holder =
        Instance.new(
            "Frame"
        )

    holder.Name =
        "DB_EnchantDust"

    holder.BackgroundTransparency = 1
    holder.BorderSizePixel = 0
    holder.Size = UDim2.fromScale(1, 1)
    holder.ClipsDescendants = true
    holder.ZIndex = zIndex
    holder.Parent = parent

    local rng =
        Random.new()

    local clusters = {}

    for i = 1, clusterCount do
        clusters[i] =
            Vector2.new(
                rng:NextNumber(
                    0.10,
                    0.90
                ),
                rng:NextNumber(
                    0.10,
                    0.90
                )
            )
    end

    local colors = {
        DB_ENCHANT_WHITE,
        DB_ENCHANT_CYAN,
        Color3.fromRGB(
            220,
            244,
            255
        ),
        Color3.fromRGB(
            195,
            225,
            255
        ),
        Color3.fromRGB(
            190,
            170,
            255
        )
    }

    local function clamp01(v)
        return math.max(
            0.02,
            math.min(
                0.98,
                v
            )
        )
    end

    local function pickPosition()
        if rng:NextNumber() < 0.77 then
            local cluster =
                clusters[
                    rng:NextInteger(
                        1,
                        #clusters
                    )
                ]

            return Vector2.new(
                clamp01(
                    cluster.X
                    + rng:NextNumber(
                        -0.18,
                        0.18
                    )
                ),
                clamp01(
                    cluster.Y
                    + rng:NextNumber(
                        -0.16,
                        0.16
                    )
                )
            )
        end

        return Vector2.new(
            rng:NextNumber(
                0.03,
                0.97
            ),
            rng:NextNumber(
                0.03,
                0.97
            )
        )
    end

    for i = 1, count do
        local dot =
            Instance.new(
                "Frame"
            )

        local size =
            rng:NextInteger(
                minSize,
                maxSize
            )

        local diamond =
            (
                i % 4 == 0
            )

        dot.AnchorPoint =
            Vector2.new(
                0.5,
                0.5
            )

        dot.Size =
            UDim2.fromOffset(
                size,
                size
            )

        local startPos =
            pickPosition()

        dot.Position =
            UDim2.fromScale(
                startPos.X,
                startPos.Y
            )

        dot.BackgroundColor3 =
            colors[
                rng:NextInteger(
                    1,
                    #colors
                )
            ]

        dot.BackgroundTransparency =
            rng:NextNumber(
                minTransparency,
                maxTransparency
            )

        dot.BorderSizePixel = 0
        dot.ZIndex = zIndex
        dot.Rotation =
            diamond
            and 45
            or 0
        dot.Parent = holder

        if not diamond then
            local corner =
                Instance.new(
                    "UICorner"
                )

            corner.CornerRadius =
                UDim.new(
                    1,
                    0
                )

            corner.Parent = dot
        end

        task.spawn(function()
            while dot.Parent
            and holder.Parent do
                local basePos =
                    pickPosition()

                dot.Position =
                    UDim2.fromScale(
                        basePos.X,
                        basePos.Y
                    )

                dot.Size =
                    UDim2.fromOffset(
                        size,
                        size
                    )

                dot.BackgroundTransparency =
                    rng:NextNumber(
                        minTransparency,
                        maxTransparency
                    )

                local goalPos =
                    UDim2.fromScale(
                        clamp01(
                            basePos.X
                            + rng:NextNumber(
                                -drift,
                                drift
                            )
                        ),
                        clamp01(
                            basePos.Y
                            + rng:NextNumber(
                                -drift,
                                drift
                            )
                        )
                    )

                TweenService:Create(
                    dot,
                    TweenInfo.new(
                        rng:NextNumber(
                            0.95,
                            2.25
                        ),
                        Enum.EasingStyle.Sine,
                        Enum.EasingDirection.InOut
                    ),
                    {
                        Position = goalPos,
                        BackgroundTransparency = 0.97,
                        Size = UDim2.fromOffset(
                            size + rng:NextInteger(
                                0,
                                2
                            ),
                            size + rng:NextInteger(
                                0,
                                2
                            )
                        ),
                        Rotation =
                            (
                                diamond
                                and 45
                                or 0
                            )
                            + rng:NextInteger(
                                -22,
                                22
                            )
                    }
                ):Play()

                task.wait(
                    rng:NextNumber(
                        0.60,
                        1.35
                    )
                )
            end
        end)
    end

    return holder
end

local Panel = Instance.new("Frame")
Panel.Name = "Panel"
