local function DBDecodeBase64(data)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

    data = data:gsub("[^" .. alphabet .. "=]", "")

    return (
        data:gsub(".", function(char)
            if char == "=" then
                return ""
            end

            local value = (alphabet:find(char, 1, true) or 1) - 1
            local bits = ""

            for i = 6, 1, -1 do
                bits =
                    bits
                    .. (
                        value % 2 ^ i
                        - value % 2 ^ (i - 1)
                        > 0
                        and "1"
                        or "0"
                    )
            end

            return bits
        end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(bits)
            if #bits ~= 8 then
                return ""
            end

            local value = 0

            for i = 1, 8 do
                if bits:sub(i, i) == "1" then
                    value = value + 2 ^ (8 - i)
                end
            end

            return string.char(value)
        end)
    )
end

