task.spawn(function()
    pcall(function()
        local writer = writefile
        local assetLoader = getcustomasset or getsynasset

        if type(writer) ~= "function"
        or type(assetLoader) ~= "function" then
            return
        end

        local logoPath = "DB_SCRIPT_D_LOGO_TRANSPARENT.png"

        writer(
            logoPath,
            DBDecodeBase64(
                [==[]==]
            )
        )

        local asset = assetLoader(logoPath)

        if asset and asset ~= "" then
            HeaderLogo.Image = asset
            HeaderLogoFallback.Visible = false

            FloatingBrandLogo.Image = asset
            FloatingBrandLogoFallback.Visible = false
        end


        local moveIconPath = "DB_MOVE_FOUR_WAY_V95.png"
        writer(
            moveIconPath,
            DBDecodeBase64(
                [==[]==]
            )
        )

        local moveAsset = assetLoader(moveIconPath)
        if moveAsset and moveAsset ~= "" then
            FloatingMoveIcon.Image = moveAsset
            FloatingMoveFallback.Visible = false
        end
    end)
end)

do
    local wallpaperBase64 = {
        [1] = [==[]==],
        [2] = [==[]==],
        [3] = [==[]==],
        [4] = [==[]==],
        [5] = [==[]==],
        [6] = [==[]==],

    }

    task.spawn(function()
        pcall(function()
            local writer = writefile
            local assetLoader = getcustomasset or getsynasset

            if type(writer) ~= "function"
            or type(assetLoader) ~= "function" then
                return
            end

            for index = 1, 6 do
                local path =
                    "DB_SCRIPT_WALLPAPER_"
                    .. tostring(index)
                    .. ".jpg"

                writer(
                    path,
                    DBDecodeBase64(
                        wallpaperBase64[index]
                    )
                )

                local asset = assetLoader(path)

                if asset
                and asset ~= "" then
                    DBWallpaper.Assets[index] = asset

                    if DBWallpaper.CurrentIndex == index then
                        DBWallpaper.Apply(index)
                    end
                end
            end

            DBWallpaper.Apply(
                DBWallpaper.CurrentIndex
            )

            DBWallpaper.SetTransparency(
                DBWallpaper.Transparency
            )
        end)
    end)
end

