local ScriptDatabase = {
    ["DB通用"] = {
        {
            Name = "DB飞行",
            Code = [====[
--[[
DB FLIGHT · 蓝白附魔独立版 V4
用途：Roblox Studio / 自己拥有的 Experience
推荐位置：
StarterPlayer > StarterPlayerScripts

本版重点：
1. 小型紧凑面板，接近参考图整体尺寸
2. 不再做成一堆分散的小卡片，采用连续分区布局
3. 第一行：关闭 / 缩小，严格各占一半
4. 第二行：上 / 加 / DB FLIGHT
5. 第三行：下 / 减 / 速度档位 / 飞
6. 初始速度档位 = 1
7. 飞行后暂停角色动画，保持僵直姿态
8. 手机摇杆 / WASD 控制移动，镜头控制角色朝向
]]

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")

local LocalPlayer = Players.LocalPlayer

-- 读取 Roblox 自带移动控制器。
-- 手机摇杆和 PC WASD 最终都会汇总到这里。
local Controls = nil

pcall(function()
    local playerScripts =
        LocalPlayer:WaitForChild(
            "PlayerScripts"
        )

    local playerModule =
        require(
            playerScripts:WaitForChild(
                "PlayerModule"
            )
        )

    Controls =
        playerModule:GetControls()
end)

------------------------------------------------------------
-- 配置
------------------------------------------------------------
local CONFIG = {
    Brand = "DB FLIGHT",

    PanelWidth = 220,
    PanelHeight = 112,

    SpeedLevel = 1,
    MinSpeedLevel = 1,

    -- 速度显示仍然是 1 / 2 / 3……
    -- 但不再设置上限。
    --
    -- 1档实际速度 = 当前普通WalkSpeed × 2
    -- 2档 = 当前普通WalkSpeed × 4
    -- 3档 = 当前普通WalkSpeed × 6
    -- 以此类推。

    Blue = Color3.fromRGB(255, 255, 255),
    Cyan = Color3.fromRGB(255, 255, 255),
    White = Color3.fromRGB(255, 255, 255),
    Purple = Color3.fromRGB(255, 255, 255),

    Glass = Color3.fromRGB(255, 255, 255),
    Glass2 = Color3.fromRGB(255, 255, 255),
    Divider = Color3.fromRGB(255, 255, 255),
}

------------------------------------------------------------
-- 状态
------------------------------------------------------------
local State = {
    Flying = false,
    SpeedLevel = CONFIG.SpeedLevel,
    Vertical = 0,

    -- 开始飞行时根据当前Humanoid.WalkSpeed计算：
    -- 普通走速 × 2。
    BaseFlightSpeed = 32,

    Character = nil,
    Humanoid = nil,
    Root = nil,

    Attachment = nil,
    Velocity = nil,
    Orientation = nil,

    OldAutoRotate = nil,
    OldPlatformStand = nil,
    OldAnimateDisabled = nil,
}

------------------------------------------------------------
-- Character
------------------------------------------------------------
local function BindCharacter(character)
    State.Character = character
    State.Humanoid = character:WaitForChild("Humanoid")
    State.Root = character:WaitForChild("HumanoidRootPart")
end

if LocalPlayer.Character then
    BindCharacter(LocalPlayer.Character)
end

LocalPlayer.CharacterAdded:Connect(function(character)
    State.Flying = false
    State.Vertical = 0
    BindCharacter(character)
end)

