local function RefreshSpeed()
    SpeedLabel.Text = tostring(State.SpeedLevel)
end

PlusButton.Activated:Connect(function()
    -- 不设上限：1、2、3、4……可以一直增加。
    State.SpeedLevel =
        State.SpeedLevel
        + 1

    RefreshSpeed()
end)

MinusButton.Activated:Connect(function()
    State.SpeedLevel =
        math.max(
            CONFIG.MinSpeedLevel,
            State.SpeedLevel - 1
        )

    RefreshSpeed()
end)

