local RefreshHomePage

local DBRuntimeState = {
    MainStatus = "运行中",
    Scripts = {},
    ScriptOrder = {}
}

------------------------------------------------------------
-- DB 紧急关停：客户端基线 / 回滚 / 会话重建
------------------------------------------------------------
local function DBGetGuiRoots()
    local roots = {}
    local seen = {}

    local function addRoot(root)
        if root
        and typeof(root) == "Instance"
        and not seen[root] then
            seen[root] = true
            roots[#roots + 1] = root
        end
    end

    pcall(function()
        addRoot(
            LocalPlayer:FindFirstChild(
                "PlayerGui"
            )
        )
    end)

    pcall(function()
        addRoot(
            game:GetService(
                "CoreGui"
            )
        )
    end)

    pcall(function()
        if type(gethui) == "function" then
            addRoot(
                gethui()
            )
        end
    end)

    return roots
end

local function DBCaptureGuiBaseline()
    local baseline = {}

    for _, root in ipairs(
        DBGetGuiRoots()
    ) do
        local ok, children =
            pcall(function()
                return root:GetChildren()
            end)

        if ok and children then
            for _, child in ipairs(
                children
            ) do
                baseline[child] = true
            end
        end
    end

    return baseline
end

local function DBCollectNewTopLevelGui(
    baseline
)
    local result = {}
    local seen = {}

    baseline =
        baseline
        or {}

    for _, root in ipairs(
        DBGetGuiRoots()
    ) do
        local ok, children =
            pcall(function()
                return root:GetChildren()
            end)

        if ok and children then
            for _, child in ipairs(
                children
            ) do
                if child ~= MainGui
                and not baseline[child]
                and not seen[child] then
                    local shouldTrack =
                        child:IsA("LayerCollector")
                        or child:IsA("Folder")

                    if shouldTrack then
                        seen[child] = true
                        result[#result + 1] =
                            child
                    end
                end
            end
        end
    end

    return result
end

local function DBDestroyInstances(list)
    local destroyed = 0

    if type(list) ~= "table" then
        return destroyed
    end

    for _, object in ipairs(list) do
        if typeof(object) == "Instance"
        and object.Parent then
            local ok =
                pcall(function()
                    object:Destroy()
                end)

            if ok then
                destroyed =
                    destroyed + 1
            end
        end
    end

    return destroyed
end

local function DBCaptureClientSnapshot()
    local snapshot = {}

    pcall(function()
        snapshot.Gravity =
            workspace.Gravity
    end)

    pcall(function()
        local camera =
            workspace.CurrentCamera

        if camera then
            snapshot.Camera = {
                FieldOfView =
                    camera.FieldOfView,
                CameraType =
                    camera.CameraType,
                CameraSubject =
                    camera.CameraSubject
            }
        end
    end)

    pcall(function()
        local lighting =
            game:GetService(
                "Lighting"
            )

        snapshot.Lighting = {
            Brightness =
                lighting.Brightness,
            ClockTime =
                lighting.ClockTime,
            FogStart =
                lighting.FogStart,
            FogEnd =
                lighting.FogEnd,
            ExposureCompensation =
                lighting.ExposureCompensation,
            GlobalShadows =
                lighting.GlobalShadows,
            Ambient =
                lighting.Ambient,
            OutdoorAmbient =
                lighting.OutdoorAmbient
        }
    end)

    pcall(function()
        local character =
            LocalPlayer.Character

        local humanoid =
            character
            and character:FindFirstChildOfClass(
                "Humanoid"
            )

        if humanoid then
            snapshot.Humanoid = {
                WalkSpeed =
                    humanoid.WalkSpeed,
                JumpPower =
                    humanoid.JumpPower,
                JumpHeight =
                    humanoid.JumpHeight,
                HipHeight =
                    humanoid.HipHeight,
                AutoRotate =
                    humanoid.AutoRotate,
                PlatformStand =
                    humanoid.PlatformStand,
                Sit =
                    humanoid.Sit,
                UseJumpPower =
                    humanoid.UseJumpPower
            }
        end
    end)

    return snapshot
end

local function DBRestoreClientSnapshot(
    snapshot
)
    if type(snapshot) ~= "table" then
        return
    end

    pcall(function()
        if snapshot.Gravity ~= nil then
            workspace.Gravity =
                snapshot.Gravity
        end
    end)

    pcall(function()
        local camera =
            workspace.CurrentCamera

        local saved =
            snapshot.Camera

        if camera
        and type(saved) == "table" then
            if saved.FieldOfView ~= nil then
                camera.FieldOfView =
                    saved.FieldOfView
            end

            if saved.CameraType ~= nil then
                camera.CameraType =
                    saved.CameraType
            end

            if saved.CameraSubject
            and saved.CameraSubject.Parent then
                camera.CameraSubject =
                    saved.CameraSubject
            else
                local character =
                    LocalPlayer.Character

                local humanoid =
                    character
                    and character:FindFirstChildOfClass(
                        "Humanoid"
                    )

                if humanoid then
                    camera.CameraSubject =
                        humanoid
                end
            end
        end
    end)

    pcall(function()
        local lighting =
            game:GetService(
                "Lighting"
            )

        local saved =
            snapshot.Lighting

        if type(saved) == "table" then
            for property, value in pairs(
                saved
            ) do
                pcall(function()
                    lighting[property] =
                        value
                end)
            end
        end
    end)

    pcall(function()
        local character =
            LocalPlayer.Character

        local humanoid =
            character
            and character:FindFirstChildOfClass(
                "Humanoid"
            )

        local saved =
            snapshot.Humanoid

        if humanoid
        and type(saved) == "table" then
            local restoreProperties = {
                "WalkSpeed",
                "JumpPower",
                "JumpHeight",
                "HipHeight",
                "AutoRotate",
                "PlatformStand",
                "Sit",
                "UseJumpPower"
            }

            for _, property in ipairs(
                restoreProperties
            ) do
                if saved[property] ~= nil then
                    pcall(function()
                        humanoid[property] =
                            saved[property]
                    end)
                end
            end
        end
    end)
end

local DBSessionGuiBaseline =
    DBCaptureGuiBaseline()

local DBSessionClientSnapshot =
    DBCaptureClientSnapshot()

local DBAbsoluteShutdownBusy = false


local function DBSetScriptStatus(name, status)
    name = tostring(name or "未命名脚本")
    status = tostring(status or "未知")

    local info =
        DBRuntimeState.Scripts[name]

    if not info then
        info = {}
        DBRuntimeState.Scripts[name] = info
        table.insert(
            DBRuntimeState.ScriptOrder,
            name
        )
    end

    info.Status = status
    info.UpdatedAt = os.clock()

    if RefreshHomePage then
        pcall(RefreshHomePage)
    end
end

local function DBSetScriptHandle(name, handle)
    name =
        tostring(
            name
            or "未命名脚本"
        )

    local info =
        DBRuntimeState.Scripts[name]

    if not info then
        info = {
            Status = "运行中",
            UpdatedAt = os.clock()
        }

        DBRuntimeState.Scripts[name] =
            info

        table.insert(
            DBRuntimeState.ScriptOrder,
            name
        )
    end

    info.Handle = handle
end

local function DBRememberScriptGui(
    name,
    baseline
)
    name =
        tostring(
            name
            or "未命名脚本"
        )

    local info =
        DBRuntimeState.Scripts[name]

    if not info then
        return
    end

    info.ManagedGui =
        info.ManagedGui
        or {}

    info.ManagedGuiSet =
        info.ManagedGuiSet
        or {}

    local found =
        DBCollectNewTopLevelGui(
            baseline
        )

    for _, object in ipairs(found) do
        if not info.ManagedGuiSet[object] then
            info.ManagedGuiSet[object] =
                true

            info.ManagedGui[#info.ManagedGui + 1] =
                object
        end
    end
end


local function DBTryCleanupHandle(handle)
    if handle == nil then
        return false
    end

    local valueType =
        typeof(handle)

    if valueType == "RBXScriptConnection" then
        local ok =
            pcall(function()
                handle:Disconnect()
            end)

        return ok
    end

    if valueType == "Instance" then
        local ok =
            pcall(function()
                handle:Destroy()
            end)

        return ok
    end

    if type(handle) == "thread" then
        local ok =
            pcall(function()
                task.cancel(handle)
            end)

        return ok
    end

    if type(handle) == "function" then
        local ok =
            pcall(handle)

        return ok
    end

    if type(handle) == "table"
    or valueType == "userdata" then
        local methodNames = {
            "Stop",
            "Shutdown",
            "Unload",
            "Destroy",
            "Disable",
            "Disconnect",
            "Cleanup",
            "Close"
        }

        for _, methodName in ipairs(
            methodNames
        ) do
            local okRead, method =
                pcall(function()
                    return handle[methodName]
                end)

            if okRead
            and type(method) == "function" then
                local okCall =
                    pcall(function()
                        method(handle)
                    end)

                if okCall then
                    return true
                end
            end
        end

        if type(handle) == "table" then
            local cleanedAny = false

            for _, child in pairs(handle) do
                local childType =
                    typeof(child)

                if childType == "RBXScriptConnection"
                or childType == "Instance"
                or type(child) == "thread"
                or type(child) == "function" then
                    if DBTryCleanupHandle(child) then
                        cleanedAny = true
                    end
                end
            end

            return cleanedAny
        end
    end

    return false
end

local function DBStopScriptByName(name)
    name =
        tostring(
            name
            or ""
        )

    local info =
        DBRuntimeState.Scripts[name]

    if not info then
        return false, "未记录"
    end

    -- 第一优先级：先关该脚本被DB追踪到的UI。
    local uiDestroyed =
        DBDestroyInstances(
            info.ManagedGui
        )

    local cleaned =
        DBTryCleanupHandle(
            info.Handle
        )

    info.Status =
        cleaned
        and "已关停"
        or (
            uiDestroyed > 0
            and "UI已关闭 · 主体已请求关停"
            or "已请求关停"
        )

    info.UpdatedAt =
        os.clock()

    if RefreshHomePage then
        pcall(RefreshHomePage)
    end

    return cleaned, info.Status
end

local function DBStopAllTrackedScripts()
    local total = 0
    local cleaned = 0

    for _, name in ipairs(
        DBRuntimeState.ScriptOrder
    ) do
        local info =
            DBRuntimeState.Scripts[name]

        if info
        and (
            info.Status == "运行中"
            or info.Status == "加载中"
        ) then
            total = total + 1

            local ok =
                DBStopScriptByName(name)

            if ok then
                cleaned = cleaned + 1
            end
        end
    end

    return total, cleaned
end


local function DBAbsoluteShutdown()
    if DBAbsoluteShutdownBusy then
        return
    end

    DBAbsoluteShutdownBusy = true
    DBRuntimeState.MainStatus =
        "绝对关停中"

    --------------------------------------------------------
    -- 1. 第一优先级：立即关闭 DB UI
    --------------------------------------------------------
    pcall(function()
        MainGui.Enabled = false
    end)

    --------------------------------------------------------
    -- 2. 关闭 DB 启动以后出现的新顶层脚本 UI
    --------------------------------------------------------
    local newGui =
        DBCollectNewTopLevelGui(
            DBSessionGuiBaseline
        )

    DBDestroyInstances(
        newGui
    )

    --------------------------------------------------------
    -- 3. 尽最大能力停止 DB 已追踪到的所有脚本
    --------------------------------------------------------
    pcall(function()
        DBStopAllTrackedScripts()
    end)

    --------------------------------------------------------
    -- 4. 恢复 DB 启动前记录的客户端本地状态
    --------------------------------------------------------
    pcall(function()
        DBRestoreClientSnapshot(
            DBSessionClientSnapshot
        )
    end)

    --------------------------------------------------------
    -- 5. 最后销毁 DB 自己的 UI
    -- 不传送、不重进、不踢出，继续留在当前服务器。
    --------------------------------------------------------
    pcall(function()
        MainGui:Destroy()
    end)

    DBRuntimeState.MainStatus =
        "已关停"
end


local function DBCloseScript()
    -- 只关闭DB自身及由DB追踪的功能，不做旧“紧急关停”的全局GUI扫描。
    pcall(function()
        DBRuntimeState.MainStatus = "已关闭"
    end)

    pcall(function()
        DBStopAllTrackedScripts()
    end)

    pcall(function()
        DBRestoreClientSnapshot(DBSessionClientSnapshot)
    end)

    pcall(function()
        local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if playerGui then
            local flightGui = playerGui:FindFirstChild("DB_FLIGHT_UI")
            if flightGui then
                flightGui:Destroy()
            end
        end
    end)

    pcall(function()
        if MainGui and MainGui.Parent then
            MainGui:Destroy()
        end
    end)
end


local function SafeLoadScript(item)
    local itemName =
        tostring(
            item and item.Name
            or "未命名脚本"
        )

    local scriptGuiBaseline =
        DBCaptureGuiBaseline()

    DBSetScriptStatus(
        itemName,
        "加载中"
    )

    task.spawn(function()
        local success, resultOrError =
            pcall(function()
                if item.Code then
                    local chunk,
                        compileError =
                        loadstring(
                            item.Code
                        )

                    if type(chunk)
                    ~= "function" then
                        error(
                            "脚本编译失败："
                            .. tostring(
                                compileError
                            )
                        )
                    end

                    return chunk()

                elseif item.Url then
                    local src =
                        game:HttpGet(
                            item.Url
                        )

                    local chunk,
                        compileError =
                        loadstring(
                            src
                        )

                    if type(chunk)
                    ~= "function" then
                        error(
                            "远程脚本编译失败："
                            .. tostring(
                                compileError
                            )
                        )
                    end

                    return chunk()
                end
            end)

        if success then
            DBSetScriptHandle(
                itemName,
                resultOrError
            )

            DBSetScriptStatus(
                itemName,
                "运行中"
            )

            -- UI有些会延迟创建，因此分两次追踪。
            task.delay(
                0.35,
                function()
                    DBRememberScriptGui(
                        itemName,
                        scriptGuiBaseline
                    )
                end
            )

            task.delay(
                1.60,
                function()
                    DBRememberScriptGui(
                        itemName,
                        scriptGuiBaseline
                    )
                end
            )

            ShowDBNotification(
                "加载成功",
                itemName,
                true
            )
        else
            DBSetScriptStatus(
                itemName,
                "加载失败"
            )

            warn(
                "❌ 脚本加载失败: "
                .. tostring(
                    resultOrError
                )
            )

            ShowDBNotification(
                "加载失败",
                itemName,
                false
            )
        end
    end)
end


