    local function getTargets()
        local player =
            LocalPlayer

        local character =
            player
            and player.Character

        local humanoid =
            character
            and character:FindFirstChildOfClass(
                "Humanoid"
            )

        local root =
            character
            and character:FindFirstChild(
                "HumanoidRootPart"
            )

        local camera =
            workspace.CurrentCamera

        return player,
            character,
            humanoid,
            root,
            camera
    end

