    local function safeNumber(value)
        local n =
            tonumber(
                value
            )

        if not n
        or n ~= n
        or n == math.huge
        or n == -math.huge then
            return nil
        end

        return n
    end

    local function formatValue(value)
        if value == nil then
            return "nil"
        end

        if type(value) == "number" then
            return string.format(
                "%.3f",
                value
            ):gsub(
                "0+$",
                ""
            ):gsub(
                "%.$",
                ""
            )
        end

        return tostring(
            value
        )
    end

