        apply.TextSize = 10
        apply.Font = Enum.Font.GothamBold
        apply.AutoButtonColor = false
        apply.ZIndex = 24
        apply.Parent = row

        AddCorner(
            apply,
            7
        )

        AddDBEnchantedBorder(
            apply,
            0.62,
            true
        )

        StylePlayerPanelButton(
            apply,
            false
        )

        local function refresh()
            local ok,
                value =
                pcall(
                    getter
                )

            if ok then
                box.Text =
                    formatValue(
                        value
                    )
            else
                box.Text = "不可用"
            end
        end

        local function commit()
            local ok,
                err =
                pcall(
                    setter,
                    box.Text
                )

            if ok then
                refresh()
            else
                warn(
                    "[DB玩家面板] "
                    .. labelText
                    .. " 修改失败: "
                    .. tostring(
                        err
                    )
                )
            end
        end

        apply.Activated:Connect(
            commit
        )

        box.FocusLost:Connect(
            function(
                enterPressed
            )
                if enterPressed then
                    commit()
                end
            end
        )

        refreshers[
            #refreshers + 1
        ] = refresh

        return refresh
    end

    local function createNumericProperty(
        section,
        labelText,
        targetGetter,
        propertyName
    )
        createValueEditor(
            section,
            labelText,
            function()
                local target =
                    targetGetter()

                return target
                    and target[
                        propertyName
                    ]
            end,
            function(raw)
                local n =
                    safeNumber(
                        raw
                    )

                if not n then
                    error(
                        "请输入有效数字"
                    )
                end

                local target =
                    targetGetter()

                if not target then
                    error(
                        "目标不存在"
                    )
                end

                target[
                    propertyName
                ] = n
            end
        )
    end

