            UDim2.new(
                0.32,
                -5,
                0,
                26
            )

        toggle.Position =
            UDim2.new(
                0.68,
                0,
                0.5,
                -13
            )

        toggle.BackgroundColor3 =
            Color3.fromRGB(
                15,
                22,
                31
            )

        toggle.BackgroundTransparency =
            0.08

        toggle.BorderSizePixel = 0
        toggle.TextSize = 10
        toggle.Font = Enum.Font.GothamBold
        toggle.AutoButtonColor = false
        toggle.ZIndex = 24
        toggle.Parent = row

        AddCorner(
            toggle,
            7
        )

        AddDBEnchantedBorder(
            toggle,
            0.62,
            true
        )

        StylePlayerPanelButton(
            toggle,
            false
        )

        local function refresh()
            local target =
                targetGetter()

            if not target then
                toggle.Text = "不可用"
                return
            end

            local ok,
                value =
                pcall(function()
                    return target[
                        propertyName
                    ]
                end)

            if not ok then
                toggle.Text = "不可用"
                return
            end

            toggle.Text =
                value
                and "开启"
                or "关闭"
        end

        toggle.Activated:Connect(function()
            local target =
                targetGetter()

            if not target then
                return
            end

            pcall(function()
                target[
                    propertyName
                ] =
                    not target[
                        propertyName
                    ]
            end)

            refresh()
        end)

        refreshers[
            #refreshers + 1
        ] = refresh

        return refresh
    end

