    local function createVectorEditor(
        section,
        labelText,
        getter,
        setter
    )
        local row =
            createRow(
                section,
                62
            )

        local label =
            Instance.new(
                "TextLabel"
            )

        label.Size =
            UDim2.new(
                1,
                -18,
                0,
                22
            )

        label.Position =
            UDim2.fromOffset(
                9,
                2
            )

        label.BackgroundTransparency = 1
        label.Text = labelText

        label.TextColor3 =
            Color3.fromRGB(
                238,
                241,
                248
            )

        label.TextSize = 10
        label.Font = Enum.Font.GothamMedium

        label.TextXAlignment =
            Enum.TextXAlignment.Left

        label.ZIndex = 24
        label.Parent = row

        local boxes = {}

        for i,
            axis in ipairs({
                "X",
                "Y",
                "Z"
            }) do
            local box =
                Instance.new(
                    "TextBox"
                )

            box.Size =
                UDim2.new(
                    0.22,
                    -4,
                    0,
                    26
                )

            box.Position =
                UDim2.new(
                    0.02
                    + (
                        i - 1
                    ) * 0.23,
                    0,
                    0,
                    30
                )

            box.BackgroundColor3 =
                Color3.fromRGB(
                    9,
                    12,
                    18
                )

            box.BackgroundTransparency =
                0.10

            box.BorderSizePixel = 0
            box.ClearTextOnFocus = false
            box.Text = ""
            box.PlaceholderText = axis

            box.TextColor3 =
                Color3.fromRGB(
                    250,
                    252,
                    255
                )

            box.PlaceholderColor3 =
                Color3.fromRGB(
                    210,
                    224,
                    240
                )

            box.TextSize = 9
            box.Font = Enum.Font.GothamMedium
            box.ZIndex = 24
            box.Parent = row

            AddCorner(
                box,
                6
            )

            boxes[
                i
            ] = box
        end

        local apply =
            Instance.new(
                "TextButton"
            )

        apply.Size =
            UDim2.new(
                0.27,
                -6,
                0,
                26
            )

        apply.Position =
            UDim2.new(
                0.72,
                0,
                0,
                30
            )

        apply.BackgroundColor3 =
            Color3.fromRGB(
                15,
                22,
                31
            )

        apply.BackgroundTransparency =
            0.08

        apply.BorderSizePixel = 0
        apply.Text = "应用"
        apply.TextSize = 9
        apply.Font = Enum.Font.GothamBold
        apply.AutoButtonColor = false
        apply.ZIndex = 24
        apply.Parent = row

        AddCorner(
            apply,
            6
        )

        AddDBEnchantedBorder(
            apply,
            0.62,
            true
        )

        StylePlayerPanelButton(
            apply,
            false
        )

        local function refresh()
            local ok,
                value =
                pcall(
                    getter
                )

            if ok
            and typeof(
                value
            ) == "Vector3" then
                boxes[1].Text =
                    formatValue(
                        value.X
                    )

                boxes[2].Text =
                    formatValue(
                        value.Y
                    )

                boxes[3].Text =
                    formatValue(
                        value.Z
                    )
            end
        end

        local function commit()
            local x =
                safeNumber(
                    boxes[1].Text
                )

            local y =
                safeNumber(
                    boxes[2].Text
                )

            local z =
                safeNumber(
                    boxes[3].Text
                )

            if not x
            or not y
            or not z then
                return
            end

            pcall(
                setter,
                Vector3.new(
                    x,
                    y,
                    z
                )
            )

            refresh()
        end

        apply.Activated:Connect(
            commit
        )

        refreshers[
            #refreshers + 1
        ] = refresh
    end

