    local function getAttrTarget()
        local player,
            character,
            humanoid =
            getTargets()

        local name =
            attrTargets[
                attrTargetIndex
            ]

        if name == "玩家" then
            return player
        elseif name == "角色" then
            return character
        end

        return humanoid
    end

    local function parseAttributeValue(
        raw
    )
        local lower =
            string.lower(
                raw
            )

        if lower == "true" then
            return true
        elseif lower == "false" then
            return false
        end

        local n =
            safeNumber(
                raw
            )

        if n then
            return n
        end

        return raw
    end

    local function refreshAttrs()
        attrTargetButton.Text =
            attrTargets[
                attrTargetIndex
            ]

        local target =
            getAttrTarget()

        if not target then
            attrList.Text =
                "目标不存在"
            return
        end

        local ok,
            attrs =
            pcall(function()
                return target:GetAttributes()
            end)

        if not ok then
            attrList.Text =
                "无法读取自定义属性"
            return
        end

        local lines = {}

        for name,
            value in pairs(
                attrs
            ) do
            lines[
                #lines + 1
            ] =
                tostring(name)
                .. " = "
                .. tostring(value)
        end

        table.sort(
            lines
        )

        if #lines == 0 then
            attrList.Text =
                "暂无自定义属性"
        else
            attrList.Text =
                table.concat(
                    lines,
                    "\n"
                )
        end
    end

    attrTargetButton.Activated:Connect(function()
        attrTargetIndex =
            attrTargetIndex % #attrTargets
            + 1

        refreshAttrs()
    end)

    setAttr.Activated:Connect(function()
        local target =
            getAttrTarget()

        if not target
        or attrName.Text == "" then
            return
        end

        pcall(function()
            target:SetAttribute(
                attrName.Text,
                parseAttributeValue(
                    attrValue.Text
                )
            )
        end)

        refreshAttrs()
    end)

    removeAttr.Activated:Connect(function()
        local target =
            getAttrTarget()

        if not target
        or attrName.Text == "" then
            return
        end

        pcall(function()
            target:SetAttribute(
                attrName.Text,
                nil
            )
        end)

        refreshAttrs()
    end)

    refreshers[
        #refreshers + 1
    ] = refreshAttrs

