    local function getObjectPath(
        object,
        root
    )
        local parts = {}
        local current = object

        while current
        and current ~= root do
            table.insert(
                parts,
                1,
                current.Name
            )

            current =
                current.Parent
        end

        return table.concat(
            parts,
            "."
        )
    end

    local function refreshValueRows()
        for _,
            child in ipairs(
                dynamicValuesHost:GetChildren()
            ) do
            if child:IsA(
                "Frame"
            ) then
                child:Destroy()
            end
        end

        local player,
            character =
            getTargets()

        local found = {}

        local function scan(
            root,
            prefix
        )
            if not root then
                return
            end

            for _,
                object in ipairs(
                    root:GetDescendants()
                ) do
                if object:IsA(
                    "IntValue"
                )
                or object:IsA(
                    "NumberValue"
                )
                or object:IsA(
                    "BoolValue"
                )
                or object:IsA(
                    "StringValue"
                ) then
                    found[
                        #found + 1
                    ] = {
                        Object = object,
                        Label =
                            prefix
                            .. "."
                            .. getObjectPath(
                                object,
                                root
                            )
                    }

                    if #found >= 40 then
                        return
                    end
                end
            end
        end

        scan(
            player,
            "玩家"
        )

        if #found < 40 then
            scan(
                character,
                "角色"
            )
        end

        if #found == 0 then
            local empty =
                Instance.new(
                    "TextLabel"
                )

            empty.Size =
                UDim2.new(
                    1,
                    0,
                    0,
                    28
                )

            empty.BackgroundTransparency = 1
            empty.Text =
                "当前没有可见的数值对象数据"

            empty.TextColor3 =
                Color3.fromRGB(
                    220,
                    232,
                    248
                )

            empty.TextSize = 9
            empty.Font = Enum.Font.GothamMedium
            empty.ZIndex = 23
            empty.Parent =
                dynamicValuesHost

            return
        end

        for index,
            info in ipairs(
                found
            ) do
            local object =
                info.Object

            local row =
                createRow(
                    dynamicValuesHost,
                    34
                )

            row.LayoutOrder =
                index

            local label =
                Instance.new(
                    "TextLabel"
                )

            label.Size =
                UDim2.new(
                    0.48,
                    -5,
                    1,
                    0
                )

            label.Position =
                UDim2.fromOffset(
                    8,
                    0
                )

            label.BackgroundTransparency = 1
            label.Text = info.Label
            label.TextTruncate =
                Enum.TextTruncate.AtEnd

            label.TextColor3 =
                Color3.fromRGB(
                    225,
                    230,
                    240
                )

            label.TextSize = 8
            label.Font = Enum.Font.GothamMedium

            label.TextXAlignment =
                Enum.TextXAlignment.Left

            label.ZIndex = 24
            label.Parent = row

            local box =
                Instance.new(
                    "TextBox"
                )

            box.Size =
                UDim2.new(
                    0.31,
                    -4,
                    0,
                    25
                )

            box.Position =
                UDim2.new(
                    0.50,
                    0,
                    0.5,
                    -12
                )

            box.BackgroundColor3 =
                Color3.fromRGB(
                    9,
                    12,
                    18
                )

            box.BackgroundTransparency =
                0.10

            box.BorderSizePixel = 0
            box.ClearTextOnFocus = false

            box.TextColor3 =
                Color3.fromRGB(
                    250,
                    252,
                    255
                )

            box.Text =
                tostring(
                    object.Value
                )

            box.TextSize = 8
            box.Font = Enum.Font.GothamMedium
            box.ZIndex = 24
            box.Parent = row

            AddCorner(
                box,
                6
            )

            local apply =
                Instance.new(
                    "TextButton"
                )

            apply.Size =
                UDim2.new(
                    0.18,
                    -5,
                    0,
                    25
                )

            apply.Position =
                UDim2.new(
                    0.82,
                    0,
                    0.5,
                    -12
                )

            apply.BackgroundColor3 =
                Color3.fromRGB(
                    15,
                    22,
                    31
                )

            apply.BackgroundTransparency =
                0.08

            apply.BorderSizePixel = 0
            apply.Text = "应用"
            apply.TextSize = 8
            apply.Font = Enum.Font.GothamBold
            apply.AutoButtonColor = false
            apply.ZIndex = 24
            apply.Parent = row

            AddCorner(
                apply,
                6
            )

            AddDBEnchantedBorder(
                apply,
                0.62,
                true
            )

            StylePlayerPanelButton(
                apply,
                false
            )

            apply.Activated:Connect(function()
                if not object.Parent then
                    return
                end

                pcall(function()
                    if object:IsA(
                        "BoolValue"
                    ) then
                        object.Value =
                            string.lower(
                                box.Text
                            ) == "true"
                    elseif object:IsA(
                        "IntValue"
                    ) then
                        object.Value =
                            math.floor(
                                safeNumber(
                                    box.Text
                                )
                                or object.Value
                            )
                    elseif object:IsA(
                        "NumberValue"
                    ) then
                        object.Value =
                            safeNumber(
                                box.Text
                            )
                            or object.Value
                    else
                        object.Value =
                            box.Text
                    end
                end)

                box.Text =
                    tostring(
                        object.Value
                    )
            end)
        end
    end

    createAction(
        valuesSection,
        "重新扫描数值对象 / 排行榜数据",
        refreshValueRows
