    --------------------------------------------------------
    -- 初始快照 / 恢复
    --------------------------------------------------------
    local restoreSection =
        createSection(
            "恢复与刷新"
        )

    local function captureSnapshot()
        local player,
            character,
            humanoid,
            root,
            camera =
            getTargets()

        if not humanoid then
            return
        end

        snapshot = {
            WalkSpeed =
                humanoid.WalkSpeed,

            JumpPower =
                humanoid.JumpPower,

            JumpHeight =
                humanoid.JumpHeight,

            HipHeight =
                humanoid.HipHeight,

            MaxSlopeAngle =
                humanoid.MaxSlopeAngle,

            Health =
                humanoid.Health,

            MaxHealth =
                humanoid.MaxHealth,

            AutoRotate =
                humanoid.AutoRotate,

            UseJumpPower =
                humanoid.UseJumpPower,

            PlatformStand =
                humanoid.PlatformStand,

            Gravity =
                workspace.Gravity,

            FOV =
                camera
                and camera.FieldOfView,

            MinZoom =
                player.CameraMinZoomDistance,

            MaxZoom =
                player.CameraMaxZoomDistance,

            CameraOffset =
                humanoid.CameraOffset,

            RootAnchored =
                root
                and root.Anchored,

            RootMassless =
                root
                and root.Massless,

            Scales = {}
        }

        for _,
            info in ipairs(
                scaleNames
            ) do
            local value =
                humanoid:FindFirstChild(
                    info[2]
                )

            if value
            and value:IsA(
                "NumberValue"
            ) then
                snapshot.Scales[
                    info[2]
                ] =
                    value.Value
            end
        end
    end

    local function restoreSnapshot()
        if not snapshot then
            return
        end

        local player,
            _,
            humanoid,
            root,
            camera =
            getTargets()

        if not humanoid then
            return
        end

        pcall(function()
            humanoid.WalkSpeed =
                snapshot.WalkSpeed

            humanoid.JumpPower =
                snapshot.JumpPower

            humanoid.JumpHeight =
                snapshot.JumpHeight

            humanoid.HipHeight =
                snapshot.HipHeight

            humanoid.MaxSlopeAngle =
                snapshot.MaxSlopeAngle

            humanoid.MaxHealth =
                snapshot.MaxHealth

            humanoid.Health =
                math.min(
                    snapshot.Health,
                    snapshot.MaxHealth
                )

            humanoid.AutoRotate =
                snapshot.AutoRotate

            humanoid.UseJumpPower =
                snapshot.UseJumpPower

            humanoid.PlatformStand =
                snapshot.PlatformStand

            humanoid.CameraOffset =
                snapshot.CameraOffset

            workspace.Gravity =
                snapshot.Gravity

            if camera
            and snapshot.FOV then
                camera.FieldOfView =
                    snapshot.FOV
            end

            player.CameraMinZoomDistance =
                snapshot.MinZoom

            player.CameraMaxZoomDistance =
                snapshot.MaxZoom

            if root then
                root.Anchored =
                    snapshot.RootAnchored

                root.Massless =
                    snapshot.RootMassless
            end

            for name,
                value in pairs(
                    snapshot.Scales
                ) do
                local scale =
                    humanoid:FindFirstChild(
                        name
                    )

                if scale
                and scale:IsA(
                    "NumberValue"
                ) then
                    scale.Value =
                        value
                end
            end
        end)

        notify(
            "已恢复打开玩家面板时保存的主要数据"
        )
    end

    createAction(
        restoreSection,
        "保存当前数据为恢复点",
        function()
            captureSnapshot()
            notify(
                "已保存当前恢复点"
            )
        end
    )

    createAction(
        restoreSection,
        "恢复保存的数据",
        restoreSnapshot
    )

    local warning =
        Instance.new(
            "TextLabel"
        )

    warning.Size =
        UDim2.new(
            1,
            0,
            0,
            48
        )

    warning.BackgroundTransparency = 1

    warning.Text =
        "说明：用户编号、账号年龄等只读信息只展示；血量、移动速度、排行榜数值等若由游戏服务器控制，修改后可能被服务器重新写回。"

    warning.TextWrapped = true

    warning.TextColor3 =
        Color3.fromRGB(
            255,
            222,
            150
        )

    warning.TextSize = 8
    warning.Font = Enum.Font.GothamMedium

    warning.TextXAlignment =
        Enum.TextXAlignment.Left

    warning.TextYAlignment =
        Enum.TextYAlignment.Top

    warning.ZIndex = 23
    warning.Parent = restoreSection

    --------------------------------------------------------
    -- 刷新
    --------------------------------------------------------
    function controller.Refresh()
        for _,
            callback in ipairs(
                refreshers
            ) do
            pcall(
                callback
            )
        end

        pcall(
            refreshValueRows
        )
    end

    function controller.Show()
        panel.Visible = true

        for _, obj in ipairs(panel:GetDescendants()) do
            if (
                obj:IsA("Frame")
                or obj:IsA("TextButton")
                or obj:IsA("TextBox")
                or obj:IsA("ScrollingFrame")
            )
            and obj.BackgroundTransparency < 0.98 then
                local c = obj.BackgroundColor3
                local luminance =
                    c.R * 0.299
                    + c.G * 0.587
                    + c.B * 0.114

                if luminance < 0.48 then
                    obj.BackgroundColor3 =
                        Color3.fromRGB(
                            255,
                            255,
                            255
                        )

                    obj.BackgroundTransparency =
                        math.max(
                            obj.BackgroundTransparency,
                            0.82
                        )
                end
            end

            if obj:IsA("UIStroke")
            and obj.Name ~= "DB_RainbowMain"
             then
                obj.Color =
                    Color3.fromRGB(
                        255,
                        255,
                        255
                    )
            end
        end

        panel.BackgroundColor3 =
            Color3.fromRGB(
                255,
                255,
                255
            )

        panel.BackgroundTransparency =
            0.82

        if not snapshot then
            captureSnapshot()
        end

        controller.Refresh()
    end

    function controller.Hide()
        panel.Visible = false
    end

    controller.Frame = panel

    refreshButton.Activated:Connect(function()
        controller.Refresh()
    end)

    LocalPlayer.CharacterAdded:Connect(function()
        task.delay(
            0.60,
            function()
                if panel.Visible then
                    snapshot = nil
                    controller.Show()
                end
            end
        )
    end)

    return controller
end

