--========================================================--
--  高科技角色预览：
--  头像 ⇄ 3D立体人物
--  类Minecraft背包人物：自动同步真实角色动作与正面转向
--========================================================--

local function CreatePlayer3DPreview()
    local PreviewRunService =
        game:GetService(
            "RunService"
        )

    local previewState = {
        Enabled = false,

        SourceCharacter = nil,
        SourceRoot = nil,

        CloneCharacter = nil,
        CloneRoot = nil,

        PartPairs = {},

        Center = Vector3.new(0, 1.5, 0),
        Distance = 7,

        -- 记录开启3D时真实人物的朝向。
        -- 之后只在正面左右90度范围内同步。
        BaseSourceYaw = 0,
        DisplayYaw = 0
    }

    --------------------------------------------------------
    -- 轻量蓝白附魔切换按钮
    --------------------------------------------------------
    local switchButton =
        Instance.new(
            "TextButton"
        )

    switchButton.Name =
        "Player3DSwitch"

    switchButton.Position =
        UDim2.fromOffset(
            3,
            28
        )

    switchButton.Size =
        UDim2.fromOffset(
            24,
            24
        )

    switchButton.BackgroundColor3 =
        Color3.fromRGB(
            12,
            22,
            34
        )

    switchButton.BackgroundTransparency =
        0.12

    switchButton.BorderSizePixel = 0
    switchButton.AutoButtonColor = false

    -- 双向切换符号，含义与参考图一致。
    switchButton.Text = "⇅"

    switchButton.TextSize = 14
    switchButton.Font =
        Enum.Font.GothamBlack

    switchButton.ZIndex = 45
    switchButton.Parent =
        PlayerInfoCard

    AddCorner(
        switchButton,
        9
    )

    AddDBEnchantedBorder(
        switchButton,
        0.72,
        true
    )

    AddDBEnchantedText(
        switchButton,
        false
    )

    --------------------------------------------------------
    -- 3D长方形预览框：
    -- 几乎占满整个玩家信息卡，仅保留很小边距。
    --------------------------------------------------------
    local viewport =
        Instance.new(
            "ViewportFrame"
        )

    viewport.Name =
        "Player3DViewport"

    -- 3D只替换“原大头像”的左侧区域。
    -- 三行玩家文字永远保留在右边。
    -- 这个区域对应用户标出的红框：
    -- 上：玩家信息标题下方
    -- 左：卡片左边
    -- 右：三行文字左边
    -- 下：好友框上沿
    viewport.Position =
        UDim2.fromOffset(
            5,
            29
        )

    viewport.Size =
        UDim2.fromOffset(
            94,
            94
        )

    viewport.BackgroundColor3 =
        Color3.fromRGB(
            7,
            12,
            20
        )

    viewport.BackgroundTransparency =
        0.035

    viewport.BorderSizePixel = 0
    viewport.Active = false

    viewport.Ambient =
        Color3.fromRGB(
            180,
            190,
            215
        )

    viewport.LightColor =
        Color3.fromRGB(
            255,
            255,
            255
        )

    viewport.LightDirection =
        Vector3.new(
            -0.55,
            -0.85,
            -0.65
        )

    viewport.ImageColor3 =
        Color3.fromRGB(
            255,
            255,
            255
        )

    viewport.ImageTransparency = 0

    viewport.Visible = false
    viewport.ZIndex = 34
    viewport.Parent =
        PlayerInfoCard

    AddCorner(
        viewport,
        10
    )

    AddDBEnchantedBorder(
        viewport,
        0.72,
        true
    )

    local world =
        Instance.new(
            "WorldModel"
        )

    world.Name =
        "DB_PlayerPreviewWorld"

    world.Parent =
        viewport

    local camera =
        Instance.new(
            "Camera"
        )

    camera.Name =
        "DB_PlayerPreviewCamera"

    camera.FieldOfView = 30
    camera.Parent =
        viewport

    viewport.CurrentCamera =
        camera

    --------------------------------------------------------
    -- 工具：建立稳定路径，配对实时角色和预览角色的BasePart
    --------------------------------------------------------
    local function GetRelativePath(
        object,
        root
    )
        local names = {}
        local current = object

        while current
        and current ~= root do
            table.insert(
                names,
                1,
                current.Name
            )

            current =
                current.Parent
        end

        return table.concat(
            names,
            "/"
        )
    end

    local function ClearPreviewCharacter()
        previewState.PartPairs = {}
        previewState.SourceCharacter = nil
        previewState.SourceRoot = nil
        previewState.CloneRoot = nil

        if previewState.CloneCharacter then
            pcall(function()
                previewState.CloneCharacter:Destroy()
            end)

            previewState.CloneCharacter = nil
        end

        for _, child in ipairs(
            world:GetChildren()
        ) do
            child:Destroy()
        end
    end

    local function UpdatePreviewCamera()
        -- 镜头固定在人物正面。
        -- 人物本身根据真实角色转向进行有限度旋转。
        camera.CFrame =
            CFrame.lookAt(
                previewState.Center
                + Vector3.new(
                    0,
                    0,
                    previewState.Distance
                ),
                previewState.Center
            )
    end

    local function GetYawFromCFrame(cf)
        local look =
            cf.LookVector

        return math.atan2(
            -look.X,
            -look.Z
        )
    end

    local function WrapAngle(angle)
        return math.atan2(
            math.sin(angle),
            math.cos(angle)
        )
    end


    local function BuildPreviewCharacter()
        ClearPreviewCharacter()

        local character =
            LocalPlayer.Character

        if not character then
            return
        end

        local sourceRoot =
            character:FindFirstChild(
                "HumanoidRootPart"
            )

        if not sourceRoot then
            return
        end

        local oldArchivable =
            character.Archivable

        character.Archivable = true

        local ok, clone =
            pcall(function()
                return character:Clone()
            end)

        character.Archivable =
            oldArchivable

        if not ok
        or not clone then
            return
        end

        clone.Name =
            "DB_Player3DClone"

        ----------------------------------------------------
        -- 不显示Tool / 道具，也不让任何脚本在Viewport里运行
        ----------------------------------------------------
        for _, object in ipairs(
            clone:GetDescendants()
        ) do
            if object:IsA("Tool")
            or object:IsA("Script")
            or object:IsA("LocalScript")
            or object:IsA("ModuleScript") then
                object:Destroy()

            elseif object:IsA("BasePart") then
                object.Anchored = true
                object.CanCollide = false
                object.CanQuery = false
                object.CanTouch = false

                object.CastShadow = false
            end
        end

        local cloneHumanoid =
            clone:FindFirstChildOfClass(
                "Humanoid"
            )

        if cloneHumanoid then
            pcall(function()
                cloneHumanoid.DisplayDistanceType =
                    Enum.HumanoidDisplayDistanceType.None
            end)
        end

        clone.Parent =
            world

        local cloneRoot =
            clone:FindFirstChild(
                "HumanoidRootPart"
            )

        if not cloneRoot then
            clone:Destroy()
            return
        end

        ----------------------------------------------------
        -- 使用路径配对身体部件。
        -- 预览每帧复制真实人物部件相对Root的CFrame，
        -- 所以真实玩家正在跑/跳/做动作时预览会同步。
        ----------------------------------------------------
        local cloneParts = {}

        for _, part in ipairs(
            clone:GetDescendants()
        ) do
            if part:IsA("BasePart") then
                cloneParts[
                    GetRelativePath(
                        part,
                        clone
                    )
                ] = part
            end
        end

        local pairsList = {}

        for _, sourcePart in ipairs(
            character:GetDescendants()
        ) do
            if sourcePart:IsA("BasePart") then
                -- Tool里的部件不进入3D预览
                local isToolPart =
                    sourcePart:FindFirstAncestorOfClass(
                        "Tool"
                    )
                    ~= nil

                if not isToolPart then
                    local key =
                        GetRelativePath(
                            sourcePart,
                            character
                        )

                    local clonePart =
                        cloneParts[key]

                    if clonePart then
                        pairsList[
                            #pairsList + 1
                        ] = {
                            Source =
                                sourcePart,

                            Clone =
                                clonePart
                        }
                    end
                end
            end
        end

        previewState.SourceCharacter =
            character

        previewState.SourceRoot =
            sourceRoot

        previewState.BaseSourceYaw =
            GetYawFromCFrame(
                sourceRoot.CFrame
            )

        -- Viewport摄像机位于人物 +Z 方向。
        -- 角色本地正面通常朝 -Z，因此基础补180°，
        -- 保证3D人物默认正面对着我们，而不是背对着我们。
        previewState.DisplayYaw =
            math.rad(180)

        previewState.CloneCharacter =
            clone

        previewState.CloneRoot =
            cloneRoot

        previewState.PartPairs =
            pairsList

        ----------------------------------------------------
        -- 先同步一次姿态，再按BoundingBox自动计算镜头距离
        ----------------------------------------------------
        for _, pair in ipairs(
            previewState.PartPairs
        ) do
            if pair.Source.Parent
            and pair.Clone.Parent then
                pair.Clone.CFrame =
                    CFrame.Angles(
                        0,
                        previewState.DisplayYaw,
                        0
                    )
                    * sourceRoot.CFrame:ToObjectSpace(
                        pair.Source.CFrame
                    )
            end
        end

        local boxCF, boxSize =
            clone:GetBoundingBox()

        previewState.Center =
            boxCF.Position

        ----------------------------------------------------
        -- 根据真实模型包围盒自动计算镜头距离。
        -- 目标：
        -- 1. 头发最顶端完整显示
        -- 2. 脚底完整显示
        -- 3. 上下左右再多留一点安全边距
        --
        -- 不再使用固定 largest * 倍率，因此不同身高、
        -- 不同头发/配饰的角色都能更稳定地完整进入框内。
        ----------------------------------------------------
        local halfFov =
            math.rad(
                camera.FieldOfView
                * 0.5
            )

        local tanHalfFov =
            math.max(
                0.01,
                math.tan(
                    halfFov
                )
            )

        local fitY =
            (
                boxSize.Y
                * 0.5
            )
            / tanHalfFov

        -- 当前Viewport接近正方形，
        -- 水平也用同一FOV估算，再取更大的一个。
        local fitX =
            (
                boxSize.X
                * 0.5
            )
            / tanHalfFov

        local depthAllowance =
            boxSize.Z
            * 0.5

        local extraMargin =
            0.42

        previewState.Distance =
            math.max(
                4.8,
                math.max(
                    fitX,
                    fitY
                )
                + depthAllowance
                + extraMargin
            )

        previewState.Yaw = 0
        previewState.Pitch = 0

        UpdatePreviewCamera()
    end

    --------------------------------------------------------
    -- 普通头像模式 ⇄ 3D模式
    --------------------------------------------------------
    local function SetPreviewEnabled(
        enabled
    )
        previewState.Enabled =
            enabled == true

        -- 只切换左侧头像区域：
        -- 2D头像 ⇄ 3D人物。
        -- 玩家名字 / 账号年龄 / 用户名 / 好友区全部始终保留。
        PlayerAvatar.Visible =
            not previewState.Enabled

        PlayerNameLabel.Visible = true
        PlayerAgeLabel.Visible = true
        PlayerUsernameLabel.Visible = true
        FriendBox.Visible = true

        viewport.Visible =
            previewState.Enabled

        if previewState.Enabled then
            BuildPreviewCharacter()
        end
    end

    switchButton.Activated:Connect(function()
        SetPreviewEnabled(
            not previewState.Enabled
        )
    end)

    --------------------------------------------------------
    -- 每帧复制真实人物当前姿态。
    -- 这是动作同步的核心，不重新播放动画，也不复制Tool。
    --------------------------------------------------------
    local renderConnection =
        PreviewRunService.RenderStepped:Connect(
            function()
                if not previewState.Enabled then
                    return
                end

                local sourceRoot =
                    previewState.SourceRoot

                local clone =
                    previewState.CloneCharacter

                if not sourceRoot
                or not sourceRoot.Parent
                or not clone
                or not clone.Parent then
                    BuildPreviewCharacter()
                    return
                end

                ------------------------------------------------
                -- 同步真实人物转向，但绝不显示背身。
                --
                -- 相对开启3D时的正面方向：
                --   左最大 -90°
                --   右最大 +90°
                -- 总可见转动范围 = 180°
                --
                -- 如果真实人物已经转到背面区域，
                -- 预览人物就停在最后一个侧面角度，
                -- 等真实人物重新回到正面半区后再继续同步。
                ------------------------------------------------
                local currentYaw =
                    GetYawFromCFrame(
                        sourceRoot.CFrame
                    )

                local rawYaw =
                    WrapAngle(
                        currentYaw
                        - previewState.BaseSourceYaw
                    )

                local maxFrontYaw =
                    math.rad(90)

                if math.abs(rawYaw)
                <= maxFrontYaw then
                    -- 180° 是“正面对镜头”的基础朝向。
                    -- 在这个基础上只允许左右各90°。
                    previewState.DisplayYaw =
                        math.rad(180)
                        + rawYaw
                end

                local previewRotation =
                    CFrame.Angles(
                        0,
                        previewState.DisplayYaw,
                        0
                    )

                ------------------------------------------------
                -- 动作仍然逐帧同步：
                -- 跑、跳、挥手等姿态全部跟真实人物一致。
                -- Tool仍然不会进入预览。
                ------------------------------------------------
                for _, pair in ipairs(
                    previewState.PartPairs
                ) do
                    local sourcePart =
                        pair.Source

                    local clonePart =
                        pair.Clone

                    if sourcePart
                    and sourcePart.Parent
                    and clonePart
                    and clonePart.Parent then
                        clonePart.CFrame =
                            previewRotation
                            * sourceRoot.CFrame:ToObjectSpace(
                                sourcePart.CFrame
                            )
                    end
                end
            end
        )

    --------------------------------------------------------
    -- 重生时自动重建3D人物
    --------------------------------------------------------
    local characterConnection =
        LocalPlayer.CharacterAdded:Connect(
            function()
                if previewState.Enabled then
                    task.delay(
                        0.45,
                        BuildPreviewCharacter
                    )
                end
            end
        )

    --------------------------------------------------------
    -- DB界面被销毁时清理连接
    --------------------------------------------------------
    PlayerInfoCard.AncestryChanged:Connect(
        function(_, parent)
            if parent ~= nil then
                return
            end

            pcall(function()
                renderConnection:Disconnect()
            end)

            pcall(function()
                characterConnection:Disconnect()
            end)
        end
    )

    return {
        Button = switchButton,
        Viewport = viewport,
        SetEnabled = SetPreviewEnabled,
        Refresh = BuildPreviewCharacter
    }
end

