local function RefreshServerPlayersRows()
    if not ServerPlayersContent
    or not ServerPlayersContent.Parent then
        return
    end

    local players =
        Players:GetPlayers()

    table.sort(
        players,
        function(a, b)
            return string.lower(
                tostring(a.DisplayName)
            )
            < string.lower(
                tostring(b.DisplayName)
            )
        end
    )

    local signatureParts = {}

    for _, player in ipairs(players) do
        signatureParts[
            #signatureParts + 1
        ] =
            tostring(
                player.UserId
            )
    end

    local signature =
        table.concat(
            signatureParts,
            ","
        )

    if signature ==
        ServerPlayersSignature then
        return
    end

    ServerPlayersSignature =
        signature

    for _, child in ipairs(
        ServerPlayersContent:GetChildren()
    ) do
        if child:IsA("TextLabel")
        and child.Name ==
            "ServerPlayerRow" then
            child:Destroy()
        end
    end

    if #players == 0 then
        local empty =
            Instance.new(
                "TextLabel"
            )

        empty.Name =
            "ServerPlayerRow"

        empty.Size =
            UDim2.new(
                1,
                -2,
                0,
                20
            )

        empty.BackgroundTransparency = 1
        empty.Text = "暂无玩家"

        empty.TextColor3 =
            Color3.fromRGB(
                190,
                194,
                204
            )

        empty.TextSize = 10

        empty.Font =
            Enum.Font.GothamMedium

        empty.TextXAlignment =
            Enum.TextXAlignment.Left

        empty.ZIndex = 25
        empty.Parent =
            ServerPlayersContent

        return
    end

    for index, player in ipairs(players) do
        local row =
            Instance.new(
                "TextLabel"
            )

        row.Name =
            "ServerPlayerRow"

        row.LayoutOrder = index

        row.Size =
            UDim2.new(
                1,
                -2,
                0,
                20
            )

        row.BackgroundColor3 =
            Color3.fromRGB(
                18,
                24,
                33
            )

        row.BackgroundTransparency =
            index % 2 == 0
            and 0.82
            or 0.92

        row.BorderSizePixel = 0

        row.Text =
            tostring(index)
            .. ". "
            .. tostring(
                player.DisplayName
            )
            .. "  (@"
            .. tostring(
                player.Name
            )
            .. ")"

        row.TextColor3 =
            Color3.fromRGB(
                242,
                246,
                252
            )

        row.TextSize = 10

        row.Font =
            Enum.Font.GothamMedium

        row.TextXAlignment =
            Enum.TextXAlignment.Left

        row.TextYAlignment =
            Enum.TextYAlignment.Center

        row.TextTruncate =
            Enum.TextTruncate.AtEnd

        row.ZIndex = 25
        row.Parent =
            ServerPlayersContent

        AddCorner(
            row,
            5
        )
    end

    task.defer(function()
        if ServerPlayersLayout
        and ServerPlayersScroll then
            local height =
                ServerPlayersLayout.AbsoluteContentSize.Y
                + 9

            ServerPlayersContent.Size =
                UDim2.new(
                    1,
                    -5,
                    0,
                    height
                )

            ServerPlayersScroll.CanvasSize =
                UDim2.fromOffset(
                    0,
                    height
                )
        end
    end)
end

