local function DBGetBeijingTimestamp()
    local unixNow = nil

    local ok, value =
        pcall(function()
            return workspace:GetServerTimeNow()
        end)

    if ok
    and type(value) == "number"
    and value > 1000000000 then
        unixNow = value
    else
        unixNow = os.time()
    end

    return os.date(
        "!%Y-%m-%d %H:%M:%S",
        math.floor(unixNow + 8 * 60 * 60)
    )
end

local function DBBuildProcessText()
    local lines = {
        "DB 主程序  ·  "
        .. DBRuntimeState.MainStatus
    }

    local shown = 0

    for i = #DBRuntimeState.ScriptOrder, 1, -1 do
        local name =
            DBRuntimeState.ScriptOrder[i]

        local info =
            DBRuntimeState.Scripts[name]

        if info then
            table.insert(
                lines,
                name
                .. "  ·  "
                .. tostring(info.Status)
            )

            shown = shown + 1

            if shown >= 4 then
                break
            end
        end
    end

    if shown == 0 then
        table.insert(
            lines,
            "外部脚本  ·  暂无"
        )
    end

    return table.concat(lines, "\n")
end

local function DBBuildPlayersText()
    local players =
        Players:GetPlayers()

    local lines = {}

    for i, p in ipairs(players) do
        table.insert(
            lines,
            tostring(i)
            .. ". "
            .. tostring(p.DisplayName)
            .. " (@"
            .. tostring(p.Name)
            .. ")"
        )
    end

    if #lines == 0 then
        return "暂无玩家"
    end

    return table.concat(
        lines,
        "\n"
    )
end

