-- DB通用 · 自瞄 / 透视
-- V99：
-- 1. 不开额外独立窗口，所有设置都在中间 ListScroll 内完成。
-- 2. 玩家阵营：好友 / 我方 / 敌人 / 中立。
-- 3. NPC：识别工作区内有Humanoid但不属于Players的模型。
-- 4. 透视最大距离上限：1,000,000 米。
------------------------------------------------------------
local RenderRightList

local DBCombat =
    (function()
        local api = {}

        local RunService =
            game:GetService(
                "RunService"
            )

        local UIS =
            game:GetService(
                "UserInputService"
            )

        local STUDS_PER_METER =
            3.5714285714

        local aim = {
            Enabled = false,
            MaxDistance = 1000,
            FOVRadius = 130,
            ShowFOV = true,
            Visibility = true,
            AliveOnly = true,
            TargetPart = "头部",
            Smoothness = 0.24,
            FOVColor = Color3.fromRGB(255, 255, 255),
            Enemy = true,
            Teammate = false,
            Friend = false,
            Neutral = true,
            NPC = true,
        }

        local esp = {
            Enabled = false,
            MaxDistance = 1500,
            AliveOnly = true,
            Enemy = true,
            Teammate = true,
            Friend = true,
            Neutral = true,
            NPC = true,

            Box = true,
            Name = true,
            Health = true,
            Distance = true,
            Type = true,

            Color = Color3.fromRGB(255, 255, 255),
            TypeColor = false,
        }

        local friendCache = {}
        local npcCache = {}
        local espObjects = {}
        local lastNpcScan = 0
        local lastEspStep = 0
        local renderConnection = nil
        local destroyed = false

        ----------------------------------------------------
        -- FOV圈
        ----------------------------------------------------
        local fov =
            Instance.new(
                "Frame"
            )

        fov.Name =
            "DB_Aimbot_FOV"

        fov.AnchorPoint =
            Vector2.new(
                0.5,
                0.5
            )

        fov.BackgroundTransparency = 1
        fov.BorderSizePixel = 0
        fov.Active = false
        fov.ZIndex = 950
        fov.Visible = false
        fov.Parent = MainGui

        local fovCorner =
            Instance.new(
                "UICorner"
            )

        fovCorner.CornerRadius =
            UDim.new(
                1,
                0
            )

        fovCorner.Parent =
            fov

        local fovStroke =
            Instance.new(
                "UIStroke"
            )

        fovStroke.ApplyStrokeMode =
            Enum.ApplyStrokeMode.Border

        fovStroke.Thickness = 1.4
        fovStroke.Transparency = 0.12
        fovStroke.Color =
            Color3.fromRGB(
                255,
                255,
                255
            )

        fovStroke.Parent =
            fov

        ----------------------------------------------------
        -- 基础识别
        ----------------------------------------------------
        local function getHumanoid(model)
            if not model then
                return nil
            end

            return model:FindFirstChildOfClass(
                "Humanoid"
            )
        end

        local function getRoot(model)
            if not model then
                return nil
            end

            return
                model:FindFirstChild(
                    "HumanoidRootPart"
                )
                or model:FindFirstChild(
                    "UpperTorso"
                )
                or model:FindFirstChild(
                    "Torso"
                )
        end

        local function alive(model)
            local humanoid =
                getHumanoid(
                    model
                )

            return
                humanoid
                and humanoid.Health > 0
        end

        local function distanceMeters(model)
            local myCharacter =
                LocalPlayer.Character

            local myRoot =
                getRoot(
                    myCharacter
                )

            local targetRoot =
                getRoot(
                    model
                )

            if not myRoot
            or not targetRoot then
                return math.huge
            end

            return
                (
                    myRoot.Position
                    - targetRoot.Position
                ).Magnitude
                / STUDS_PER_METER
        end

        local function isFriend(player)
            if not player
            or player == LocalPlayer then
                return false
            end

            local cached =
                friendCache[
                    player.UserId
                ]

            if cached ~= nil then
                return cached
            end

            local result = false

            pcall(function()
                result =
                    LocalPlayer:IsFriendsWith(
                        player.UserId
                    )
            end)

            friendCache[
                player.UserId
            ] =
                result

            return result
        end

        local function classifyPlayer(player)
            if isFriend(
                player
            ) then
                return "好友"
            end

            local myTeam =
                LocalPlayer.Team

            local theirTeam =
                player
                and player.Team

            if myTeam
            and theirTeam then
                if myTeam
                == theirTeam then
                    return "我方"
                end

                return "敌人"
            end

            return "中立"
        end

        local function allowed(
            kind,
            config
        )
            if kind == "敌人" then
                return config.Enemy
            elseif kind == "我方" then
                return config.Teammate
            elseif kind == "好友" then
                return config.Friend
            elseif kind == "NPC" then
                return config.NPC
            end

            return config.Neutral
        end

        local function kindColor(kind)
            if not esp.TypeColor then
                return esp.Color
            end

            if kind == "敌人" then
                return Color3.fromRGB(
                    255,
                    92,
                    92
                )
            elseif kind == "我方" then
                return Color3.fromRGB(
                    90,
                    255,
                    130
                )
            elseif kind == "好友" then
                return Color3.fromRGB(
                    90,
                    220,
                    255
                )
            elseif kind == "NPC" then
                return Color3.fromRGB(
                    255,
                    220,
                    92
                )
            end

            return esp.Color
        end

        ----------------------------------------------------
        -- NPC缓存
        ----------------------------------------------------
        local function scanNPCs()
            if os.clock()
            - lastNpcScan < 1.35 then
                return
            end

            lastNpcScan =
                os.clock()

            table.clear(
                npcCache
            )

            local count = 0

            for _,
                obj in ipairs(
                    workspace:GetDescendants()
                ) do
                if obj:IsA(
                    "Humanoid"
                ) then
                    local model =
                        obj.Parent

                    if model
                    and model:IsA(
                        "Model"
                    )
                    and not Players:GetPlayerFromCharacter(
                        model
                    )
                    and getRoot(
                        model
                    ) then
                        count =
                            count + 1

                        npcCache[
                            count
                        ] =
                            model

                        if count >= 160 then
                            break
                        end
                    end
                end
            end
        end

        local function entities(
            includeNPC
        )
            local result = {}

            for _,
                player in ipairs(
                    Players:GetPlayers()
                ) do
                if player
                ~= LocalPlayer
                and player.Character then
                    result[
                        #result + 1
                    ] = {
                        Model =
                            player.Character,

                        Player =
                            player,

                        Kind =
                            classifyPlayer(
                                player
                            )
                    }
                end
            end

            if includeNPC then
                scanNPCs()

                for _,
                    model in ipairs(
                        npcCache
                    ) do
                    if model
                    and model.Parent then
                        result[
                            #result + 1
                        ] = {
                            Model =
                                model,

                            Player =
                                nil,

                            Kind =
                                "NPC"
                        }
                    end
                end
            end

            return result
        end

        ----------------------------------------------------
        -- 瞄准部位
        ----------------------------------------------------
        local function fixedPart(
            model,
            mode
        )
            if mode == "头部" then
                return
                    model:FindFirstChild(
                        "Head"
                    )
                    or getRoot(
                        model
                    )
            elseif mode == "胸部" then
                return
                    model:FindFirstChild(
                        "UpperTorso"
                    )
                    or model:FindFirstChild(
                        "Torso"
                    )
                    or getRoot(
                        model
                    )
            elseif mode == "腰部" then
                return
                    model:FindFirstChild(
                        "HumanoidRootPart"
                    )
                    or getRoot(
                        model
                    )
            end

            return nil
        end

        local function targetPart(
            model,
            mode,
            camera,
            center
        )
            local fixed =
                fixedPart(
                    model,
                    mode
                )

            if fixed then
                return fixed
            end

            local candidates = {
                model:FindFirstChild(
                    "Head"
                ),
                model:FindFirstChild(
                    "UpperTorso"
                ),
                model:FindFirstChild(
                    "Torso"
                ),
                model:FindFirstChild(
                    "HumanoidRootPart"
                ),
            }

            local best = nil
            local bestDistance =
                math.huge

            for _,
                part in ipairs(
                    candidates
                ) do
                if part
                and part:IsA(
                    "BasePart"
                ) then
                    local screen,
                        visible =
                        camera:WorldToViewportPoint(
                            part.Position
                        )

                    if visible
                    and screen.Z > 0 then
                        local d =
                            (
                                Vector2.new(
                                    screen.X,
                                    screen.Y
                                )
                                - center
                            ).Magnitude

                        if d
                        < bestDistance then
                            bestDistance = d
                            best = part
                        end
                    end
                end
            end

            return
                best
                or getRoot(
                    model
                )
        end

        local function canSee(
            model,
            part,
            camera
        )
            local params =
                RaycastParams.new()

            params.FilterType =
                Enum.RaycastFilterType.Exclude

            local ignore = {}

            if LocalPlayer.Character then
                ignore[
                    #ignore + 1
                ] =
                    LocalPlayer.Character
            end

            ignore[
                #ignore + 1
            ] =
                model

            params.FilterDescendantsInstances =
                ignore

            local origin =
                camera.CFrame.Position

            local direction =
                part.Position
                - origin

            local hit =
                workspace:Raycast(
                    origin,
                    direction,
                    params
                )

            return hit == nil
        end

        ----------------------------------------------------
        -- 自瞄目标选择
        ----------------------------------------------------
        local function bestAimTarget()
            local camera =
                workspace.CurrentCamera

            if not camera then
                return nil
            end

            local vp =
                camera.ViewportSize

            local center =
                Vector2.new(
                    vp.X / 2,
                    vp.Y / 2
                )

            local bestPart = nil
            local bestScreenDistance =
                math.huge

            for _,
                entity in ipairs(
                    entities(
                        aim.NPC
                    )
                ) do
                local model =
                    entity.Model

                if allowed(
                    entity.Kind,
                    aim
                )
                and (
                    not aim.AliveOnly
                    or alive(
                        model
                    )
                ) then
                    local meters =
                        distanceMeters(
                            model
                        )

                    if meters
                    <= aim.MaxDistance then
                        local part =
                            targetPart(
                                model,
                                aim.TargetPart,
                                camera,
                                center
                            )

                        if part then
                            local screen,
                                onScreen =
                                camera:WorldToViewportPoint(
                                    part.Position
                                )

                            if onScreen
                            and screen.Z > 0 then
                                local screenDistance =
                                    (
                                        Vector2.new(
                                            screen.X,
                                            screen.Y
                                        )
                                        - center
                                    ).Magnitude

                                if screenDistance
                                <= aim.FOVRadius
                                and screenDistance
                                < bestScreenDistance
                                and (
                                    not aim.Visibility
                                    or canSee(
                                        model,
                                        part,
                                        camera
                                    )
                                ) then
                                    bestScreenDistance =
                                        screenDistance

                                    bestPart =
                                        part
                                end
                            end
                        end
                    end
                end
            end

            return bestPart
        end

        ----------------------------------------------------
        -- ESP对象
        ----------------------------------------------------
        local function createEspObject(model)
            local box =
                Instance.new(
                    "Frame"
                )

            box.Name =
                "DB_ESP_Box"

            box.BackgroundTransparency = 1
            box.BorderSizePixel = 0
            box.Active = false
            box.Visible = false
            box.ZIndex = 930
            box.Parent = MainGui

            local stroke =
                Instance.new(
                    "UIStroke"
                )

            stroke.Name =
                "BoxStroke"

            stroke.ApplyStrokeMode =
                Enum.ApplyStrokeMode.Border

            stroke.Thickness = 1.25
            stroke.Transparency = 0.08
            stroke.Parent = box

            local name =
                Instance.new(
                    "TextLabel"
                )

            name.Name =
                "NameLabel"

            name.AnchorPoint =
                Vector2.new(
                    0,
                    1
                )

            name.Position =
                UDim2.fromOffset(
                    0,
                    -3
                )

            name.Size =
                UDim2.new(
                    1,
                    0,
                    0,
                    18
                )

            name.BackgroundTransparency = 1
            name.TextColor3 = Color3.fromRGB(255, 255, 255)
            name.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
            name.TextStrokeTransparency = 0.25
            name.TextSize = 12
            name.Font = Enum.Font.GothamBlack
            name.TextXAlignment = Enum.TextXAlignment.Center
            name.ZIndex = 932
            name.Parent = box

            local info =
                Instance.new(
                    "TextLabel"
                )

            info.Name =
                "InfoLabel"

            info.Position =
                UDim2.new(
                    0,
                    0,
                    1,
                    3
                )

            info.Size =
                UDim2.new(
                    1,
                    0,
                    0,
                    18
                )

