        local function getEspObject(model)
            local obj =
                espObjects[
                    model
                ]

            if obj
            and obj.Box
            and obj.Box.Parent then
                return obj
            end

            return
                createEspObject(
                    model
                )
        end

        local function screenBounds(
            model,
            camera
        )
            local ok,
                cf,
                size =
                pcall(function()
                    local c,
                        s =
                        model:GetBoundingBox()

                    return c,
                        s
                end)

            if not ok
            or not cf
            or not size then
                return nil
            end

            local hx =
                size.X / 2

            local hy =
                size.Y / 2

            local hz =
                size.Z / 2

            local minX =
                math.huge

            local minY =
                math.huge

            local maxX =
                -math.huge

            local maxY =
                -math.huge

            local any = false

            for _,
                x in ipairs({
                    -hx,
                    hx
                }) do
                for _,
                    y in ipairs({
                        -hy,
                        hy
                    }) do
                    for _,
                        z in ipairs({
                            -hz,
                            hz
                        }) do
                        local world =
                            cf:PointToWorldSpace(
                                Vector3.new(
                                    x,
                                    y,
                                    z
                                )
                            )

                        local screen =
                            camera:WorldToViewportPoint(
                                world
                            )

                        if screen.Z > 0 then
                            any = true

                            minX =
                                math.min(
                                    minX,
                                    screen.X
                                )

                            minY =
                                math.min(
                                    minY,
                                    screen.Y
                                )

                            maxX =
                                math.max(
                                    maxX,
                                    screen.X
                                )

                            maxY =
                                math.max(
                                    maxY,
                                    screen.Y
                                )
                        end
                    end
                end
            end

            if not any then
                return nil
            end

            if maxX < 0
            or maxY < 0
            or minX > camera.ViewportSize.X
            or minY > camera.ViewportSize.Y then
                return nil
            end

            local width =
                math.max(
                    8,
                    maxX - minX
                )

            local height =
                math.max(
                    12,
                    maxY - minY
                )

            return minX,
                minY,
                width,
                height
        end

        local function updateESP()
            if not esp.Enabled then
                for _,
                    obj in pairs(
                        espObjects
                    ) do
                    if obj.Box then
                        obj.Box.Visible =
                            false
                    end
                end

                return
            end

            local camera =
                workspace.CurrentCamera

            if not camera then
                return
            end

            local live = {}

            for _,
                entity in ipairs(
                    entities(
                        esp.NPC
                    )
                ) do
                local model =
                    entity.Model

                if allowed(
                    entity.Kind,
                    esp
                )
                and (
                    not esp.AliveOnly
                    or alive(
                        model
                    )
                ) then
                    local meters =
                        distanceMeters(
                            model
                        )

                    if meters
                    <= esp.MaxDistance then
                        local x,
                            y,
                            w,
                            h =
                            screenBounds(
                                model,
                                camera
                            )

                        if x then
                            live[
                                model
                            ] =
                                true

                            local obj =
                                getEspObject(
                                    model
                                )

                            local color =
                                kindColor(
                                    entity.Kind
                                )

                            obj.Box.Position =
                                UDim2.fromOffset(
                                    x,
                                    y
                                )

                            obj.Box.Size =
                                UDim2.fromOffset(
                                    w,
                                    h
                                )

                            obj.Box.Visible =
                                true

                            obj.Stroke.Enabled =
                                esp.Box

                            obj.Stroke.Color =
                                color

                            obj.Name.TextColor3 =
                                color

                            obj.Info.TextColor3 =
                                color

                            local player =
                                entity.Player

                            if player then
                                obj.Name.Text =
                                    player.DisplayName
                                    .. " (@"
                                    .. player.Name
                                    .. ")"
                            else
                                obj.Name.Text =
                                    model.Name
                            end

                            obj.Name.Visible =
                                esp.Name

                            local humanoid =
                                getHumanoid(
                                    model
                                )

                            local infoParts = {}

                            if esp.Health
                            and humanoid then
                                infoParts[
                                    #infoParts + 1
                                ] =
                                    "HP "
                                    .. tostring(
                                        math.floor(
                                            humanoid.Health
                                            + 0.5
                                        )
                                    )
                                    .. "/"
                                    .. tostring(
                                        math.floor(
                                            humanoid.MaxHealth
                                            + 0.5
                                        )
                                    )
                            end

                            if esp.Distance then
                                infoParts[
                                    #infoParts + 1
                                ] =
                                    tostring(
                                        math.floor(
                                            meters
                                            + 0.5
                                        )
                                    )
                                    .. "m"
                            end

                            if esp.Type then
                                infoParts[
                                    #infoParts + 1
                                ] =
                                    entity.Kind
                            end

                            obj.Info.Text =
                                table.concat(
                                    infoParts,
                                    "  |  "
                                )

                            obj.Info.Visible =
                                (
                                    esp.Health
                                    or esp.Distance
                                    or esp.Type
                                )

                            obj.HealthBack.Visible =
                                esp.Health
                                and humanoid ~= nil

                            if humanoid then
                                local ratio =
                                    math.clamp(
                                        humanoid.Health
                                        / math.max(
                                            1,
                                            humanoid.MaxHealth
                                        ),
                                        0,
                                        1
                                    )

                                obj.Health.Size =
                                    UDim2.fromScale(
                                        1,
                                        ratio
                                    )

                                obj.Health.BackgroundColor3 =
                                    Color3.fromRGB(
                                        math.floor(
                                            255
                                            * (
                                                1 - ratio
                                            )
                                        ),
                                        math.floor(
                                            255
                                            * ratio
                                        ),
                                        70
                                    )
                            end
                        end
                    end
                end
            end

            for model,
                obj in pairs(
                    espObjects
                ) do
                if not live[
                    model
                ] then
                    if obj.Box then
                        obj.Box.Visible =
                            false
                    end

                    if not model.Parent then
                        if obj.Box then
                            obj.Box:Destroy()
                        end

                        espObjects[
                            model
                        ] =
                            nil
                    end
                end
            end
        end

