            switch.Text = ""
            switch.AutoButtonColor = false
            switch.ZIndex = 22
            switch.Parent = row

            AddCorner(
                switch,
                99
            )

            local dot =
                Instance.new(
                    "Frame"
                )

            dot.AnchorPoint =
                Vector2.new(
                    0.5,
                    0.5
                )

            dot.Size =
                UDim2.fromOffset(
                    16,
                    16
                )

            dot.BackgroundColor3 =
                Color3.fromRGB(
                    255,
                    255,
                    255
                )

            dot.BorderSizePixel = 0
            dot.ZIndex = 23
            dot.Parent = switch

            AddCorner(
                dot,
                99
            )

            local function refresh()
                local on =
                    config[
                        key
                    ]

                switch.BackgroundColor3 =
                    on
                    and Color3.fromRGB(
                        235,
                        235,
                        240
                    )
                    or Color3.fromRGB(
                        105,
                        105,
                        112
                    )

                switch.BackgroundTransparency =
                    on
                    and 0.38
                    or 0.55

                dot.Position =
                    on
                    and UDim2.new(
                        1,
                        -11,
                        0.5,
                        0
                    )
                    or UDim2.new(
                        0,
                        11,
                        0.5,
                        0
                    )
            end

            refresh()

            switch.Activated:Connect(function()
                config[
                    key
                ] =
                    not config[
                        key
                    ]

                TweenService:Create(
                    dot,
                    TweenInfo.new(
                        0.14,
                        Enum.EasingStyle.Quad,
                        Enum.EasingDirection.Out
                    ),
                    {
                        Position =
                            config[key]
                            and UDim2.new(
                                1,
                                -11,
                                0.5,
                                0
                            )
                            or UDim2.new(
                                0,
                                11,
                                0.5,
                                0
                            )
                    }
                ):Play()

                refresh()
            end)

            return row
        end

