                )

            btn.TextColor3 = Color3.fromRGB(255, 255, 255)
            btn.TextSize = 10
            btn.Font = Enum.Font.GothamBlack
            btn.AutoButtonColor = false
            btn.ZIndex = 22
            btn.Parent = row

            StyleLiquidButton(
                btn,
                7,
                false
            )

            btn.Activated:Connect(function()
                local current =
                    config[
                        key
                    ]

                local index = 1

                for i,
                    value in ipairs(
                        values
                    ) do
                    if value
                    == current then
                        index = i
                        break
                    end
                end

                index =
                    index % #values
                    + 1

                config[
                    key
                ] =
                    values[
                        index
                    ]

                btn.Text =
                    tostring(
                        config[
                            key
                        ]
                    )
            end)

            return row
        end

