                    0,
                    5
                )

            layout.Parent =
                scroll

            local padding =
                Instance.new(
                    "UIPadding"
                )

            padding.PaddingLeft =
                UDim.new(
                    0,
                    5
                )

            padding.PaddingRight =
                UDim.new(
                    0,
                    5
                )

            padding.Parent =
                scroll

            local swatches = {}

            local function refreshSelected()
                preview.BackgroundColor3 =
                    config[
                        key
                    ]

                for _,
                    data in ipairs(
                        swatches
                    ) do
                    local selected =
                        data.Color
                        == config[
                            key
                        ]

                    data.Stroke.Thickness =
                        selected
                        and 2.2
                        or 0.8

                    data.Stroke.Transparency =
                        selected
                        and 0.05
                        or 0.58
                end
            end

            for index,
                colorInfo in ipairs(
                    palette
                ) do
                local colorName =
                    colorInfo[
                        1
                    ]

                local colorValue =
                    colorInfo[
                        2
                    ]

                local button =
                    Instance.new(
                        "TextButton"
                    )

                button.Name =
                    "Color_"
                    .. colorName

                button.Size =
                    UDim2.fromOffset(
                        28,
                        28
                    )

                button.BackgroundColor3 =
                    colorValue

                button.BackgroundTransparency = 0
                button.BorderSizePixel = 0
                button.Text = ""
                button.AutoButtonColor = false
                button.LayoutOrder = index
                button.ZIndex = 24
                button.Parent = scroll

                AddCorner(
                    button,
                    7
                )

                local stroke =
                    Instance.new(
                        "UIStroke"
                    )

                stroke.Color =
                    Color3.fromRGB(
                        255,
                        255,
                        255
                    )

                stroke.Thickness = 0.8
                stroke.Transparency = 0.58
                stroke.Parent = button

                table.insert(
                    swatches,
                    {
                        Color = colorValue,
                        Stroke = stroke
                    }
                )

                button.Activated:Connect(function()
                    config[
                        key
                    ] =
                        colorValue

                    selector.Text =
                        labelText
                        .. "："
                        .. colorName
                        .. "  ◀ 左右滑动查看更多 ▶"

                    refreshSelected()
                end)
            end

            refreshSelected()

            return row
        end

        local function slider(
            labelText,
            config,
            key,
            minimum,
            maximum,
            order,
            integer
        )
            local row =
                rowFrame(
                    46,
                    order
                )

            local label =
                Instance.new(
                    "TextLabel"
                )

            label.Position =
                UDim2.fromOffset(
                    10,
                    2
                )

            label.Size =
                UDim2.new(
                    1,
                    -20,
                    0,
                    18
                )

            label.BackgroundTransparency = 1
            label.TextColor3 = Color3.fromRGB(255, 255, 255)
            label.TextSize = 11
            label.Font = Enum.Font.GothamBold
            label.TextXAlignment = Enum.TextXAlignment.Left
            label.ZIndex = 21
            label.Parent = row

            local bar =
                Instance.new(
                    "Frame"
                )

            bar.Position =
                UDim2.new(
                    0,
                    12,
                    0,
                    31
                )

            bar.Size =
                UDim2.new(
                    1,
                    -24,
                    0,
                    5
                )

            bar.BackgroundColor3 =
                Color3.fromRGB(
                    255,
                    255,
                    255
                )

            bar.BackgroundTransparency =
                0.68

            bar.BorderSizePixel = 0
            bar.Active = true
            bar.ZIndex = 22
            bar.Parent = row

            AddCorner(
                bar,
                99
            )

            local fill =
                Instance.new(
                    "Frame"
                )

            fill.Size =
                UDim2.fromScale(
                    0,
                    1
                )

            fill.BackgroundColor3 =
                Color3.fromRGB(
                    255,
                    255,
                    255
                )

            fill.BackgroundTransparency =
                0.12

            fill.BorderSizePixel = 0
            fill.ZIndex = 23
            fill.Parent = bar

            AddCorner(
                fill,
                99
            )

            local knob =
                Instance.new(
                    "Frame"
                )

            knob.AnchorPoint =
                Vector2.new(
                    0.5,
                    0.5
                )

            knob.Size =
                UDim2.fromOffset(
                    14,
                    14
                )

            knob.BackgroundColor3 =
                Color3.fromRGB(
                    255,
                    255,
                    255
                )

            knob.BorderSizePixel = 0
            knob.ZIndex = 24
            knob.Parent = bar

            AddCorner(
                knob,
                99
            )

            local dragging = false
            local dragInput = nil

            local function refresh()
                local value =
                    math.clamp(
                        config[
                            key
                        ],
                        minimum,
                        maximum
                    )

                local ratio =
                    (
                        value
                        - minimum
                    )
                    / (
                        maximum
                        - minimum
                    )

                fill.Size =
                    UDim2.fromScale(
                        ratio,
                        1
                    )

                knob.Position =
                    UDim2.fromScale(
                        ratio,
                        0.5
                    )

                local shown =
                    integer
                    and math.floor(
                        value
                        + 0.5
                    )
                    or math.floor(
                        value
                        * 100
                        + 0.5
                    )
                        / 100

                label.Text =
                    labelText
                    .. "："
                    .. tostring(
                        shown
                    )
            end

            local function setFromX(x)
                if not bar.Parent then
                    return
                end

                local ratio =
                    math.clamp(
                        (
                            x
                            - bar.AbsolutePosition.X
                        )
                        / math.max(
                            1,
                            bar.AbsoluteSize.X
                        ),
                        0,
                        1
                    )

                local value =
                    minimum
                    + (
                        maximum
                        - minimum
                    )
                    * ratio

                if integer then
                    value =
                        math.floor(
                            value
                            + 0.5
                        )
                end

                config[
                    key
                ] =
                    value

                refresh()
            end

            refresh()

            bar.InputBegan:Connect(function(input)
                if input.UserInputType
                == Enum.UserInputType.MouseButton1
                or input.UserInputType
                == Enum.UserInputType.Touch then
                    dragging = true
                    dragInput =
                        input

                    setFromX(
                        input.Position.X
                    )
                end
            end)

            UIS.InputChanged:Connect(function(input)
                if not dragging
                or not row.Parent then
                    return
                end

                if input.UserInputType
                == Enum.UserInputType.MouseMovement
                or (
                    input.UserInputType
                    == Enum.UserInputType.Touch
                    and input
                    == dragInput
                ) then
                    setFromX(
                        input.Position.X
                    )
                end
            end)

            UIS.InputEnded:Connect(function(input)
                if input.UserInputType
                == Enum.UserInputType.MouseButton1
                or input
                == dragInput then
                    dragging = false
                    dragInput = nil
                end
            end)

            return row
        end

