        ----------------------------------------------------
        -- 每帧更新
        ----------------------------------------------------
        local function render(dt)
            if destroyed then
                return
            end

            local camera =
                workspace.CurrentCamera

            if camera then
                local vp =
                    camera.ViewportSize

                local diameter =
                    aim.FOVRadius
                    * 2

                fov.Position =
                    UDim2.fromOffset(
                        vp.X / 2,
                        vp.Y / 2
                    )

                fov.Size =
                    UDim2.fromOffset(
                        diameter,
                        diameter
                    )

                fovStroke.Color =
                    aim.FOVColor

                fov.Visible =
                    aim.Enabled
                    and aim.ShowFOV

                if aim.Enabled
                and not UIS:GetFocusedTextBox() then
                    local part =
                        bestAimTarget()

                    if part
                    and part.Parent then
                        local desired =
                            CFrame.lookAt(
                                camera.CFrame.Position,
                                part.Position
                            )

                        camera.CFrame =
                            camera.CFrame:Lerp(
                                desired,
                                math.clamp(
                                    aim.Smoothness,
                                    0.05,
                                    1
                                )
                            )
                    end
                end
            end

            lastEspStep =
                lastEspStep
                + dt

            if lastEspStep
            >= 0.045 then
                lastEspStep = 0
                updateESP()
            end
        end

        function api.Destroy()
            if destroyed then
                return
            end

            destroyed = true

            if renderConnection then
                renderConnection:Disconnect()
                renderConnection = nil
            end

            if fov then
                fov:Destroy()
            end

            for _,
                obj in pairs(
                    espObjects
                ) do
                if obj.Box then
                    obj.Box:Destroy()
                end
            end

            table.clear(
                espObjects
            )
        end

        renderConnection =
            RunService.RenderStepped:Connect(
                render
            )

        pcall(function()
            MainGui.Destroying:Connect(
                function()
                    api.Destroy()
                end
            )
        end)

        return api
    end)()

RenderRightList = function(categoryName)

    HomePanel.Visible = false

    if PlayerControlPanel then
        PlayerControlPanel.Hide()
    end

    local oldDetail =
        RightList:FindFirstChild(
            "DB_ScriptCollectionDetail"
        )

    if oldDetail then
        oldDetail:Destroy()
    end

    ListScroll.Visible = true

    for _, child in ipairs(
        ListScroll:GetChildren()
    ) do
        if child:IsA("GuiObject") then
            child:Destroy()
        end
    end

    ListScroll.CanvasPosition =
        Vector2.new(
            0,
            0
        )

    local list = ScriptDatabase[categoryName] or {}
    for _, item in ipairs(list) do
        local btn = Instance.new("TextButton")
        btn.Name = item.Name

        DBApplyRightFullWidthButton(
            btn,
            32
        )

        btn.BackgroundColor3 = UI.Button
        btn.BackgroundTransparency = 0.24
        btn.BorderSizePixel = 0
        btn.Text = item.Name
        btn.TextColor3 = UI.Text
        btn.TextTransparency = 0
        btn.TextSize = 12
        btn.Font = Enum.Font.GothamBlack
        btn.TextXAlignment = Enum.TextXAlignment.Left
        btn.TextTruncate = Enum.TextTruncate.AtEnd
        btn.AutoButtonColor = false
        btn.ZIndex = 15

        StyleLiquidButton(btn, 9, false)

        if categoryName == "DB通用" then
            btn.BackgroundColor3 = DBVisualSettings.ButtonBackground
            btn.BackgroundTransparency = DBVisualSettings.ButtonTransparency
            btn.TextColor3 = Color3.fromRGB(255, 255, 255)
            btn.TextStrokeTransparency = 0.62
        end

        local pad = Instance.new("UIPadding")
        pad.PaddingLeft = UDim.new(0, 12)
        pad.PaddingRight = UDim.new(0, 12)
        pad.Parent = btn

        ApplySafeClickEffect(btn, function()
            if item.Page == "Aimbot" then
                DBCombat.ShowAimbot()
            elseif item.Page == "ESP" then
                DBCombat.ShowESP()
            else
                SafeLoadScript(item)
            end
        end)

        btn.Parent = ListScroll
    end
end

local function DBCreateSimpleRailButton(
    objectName,
    labelText,
    layoutOrder,
    callback
)
    local button =
        Instance.new(
            "TextButton"
        )

    button.Name =
        objectName

    DBApplyUnifiedButton(
        button,
        34
    )

    button.BackgroundColor3 =
        DBVisualSettings.ButtonBackground

    button.BackgroundTransparency =
        DBVisualSettings.ButtonTransparency

    button.BorderSizePixel = 0
    button.Text = labelText
    button.TextColor3 = Color3.fromRGB(255, 255, 255)
    button.TextSize = 14
    button.Font = Enum.Font.GothamBlack
    button.TextXAlignment = Enum.TextXAlignment.Left
    button.AutoButtonColor = false
    button.ZIndex = 16
    button.LayoutOrder = layoutOrder

    StyleLiquidButton(
        button,
        11,
        false
    )

    local pad =
        Instance.new(
            "UIPadding"
        )

    pad.PaddingLeft =
        UDim.new(
            0,
            DB_UNIFIED_SIDE_PAD
        )

    pad.PaddingRight =
        UDim.new(
            0,
            DB_UNIFIED_SIDE_PAD
        )

    pad.Parent =
        button

    ApplySafeClickEffect(
        button,
        callback
    )

    button.Parent =
        MenuScroll

    return button
end

